"use client"

import * as React from "react"
import {
  type ColumnDef,
  type ColumnFiltersState,
  type RowSelectionState,
  type SortingState,
  type VisibilityState,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table"
import { Columns3Icon, SearchIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Spinner } from "@/components/ui/spinner"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { cn } from "@/lib/utils"

export type DataTablePaginationState = {
  pageIndex: number
  pageSize: number
  count: number | null
  hasMore?: boolean
  onPageChange: (pageIndex: number) => void
  loading?: boolean
}

export type DataTableServerState = DataTablePaginationState & {
  search: string
  onSearchChange: (search: string) => void
}

export type DataTableVariant = "default" | "pane"

type DataTableProps<TData, TValue> = {
  /** Pane layout fills an embedded workspace without an outer card or inset. */
  variant?: DataTableVariant
  serverState?: DataTableServerState
  /** External pages with local filtering of the already loaded page. */
  paginationState?: DataTablePaginationState
  columns: ColumnDef<TData, TValue>[]
  data: TData[]
  searchPlaceholder?: string
  /** Global filter across all filterable columns. */
  enableGlobalFilter?: boolean
  pageSize?: number
  className?: string
  toolbarEnd?: React.ReactNode
  onRowClick?: (row: TData) => void
  isRowActive?: (row: TData) => boolean
  showSelectionSummary?: boolean
}

/**
 * Reusable DataTable (shadcn + TanStack Table):
 * search, column visibility, row selection state, pagination.
 */
export function DataTable<TData, TValue>({
  variant = "default",
  columns,
  data,
  serverState,
  paginationState,
  searchPlaceholder = "Search…",
  enableGlobalFilter = true,
  pageSize = 10,
  className,
  toolbarEnd,
  onRowClick,
  isRowActive,
  showSelectionSummary = true,
}: DataTableProps<TData, TValue>) {
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([])
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>({})
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({})
  const [globalFilter, setGlobalFilter] = React.useState("")
  const pagination = serverState ?? paginationState

  const table = useReactTable({
    data,
    columns,
    initialState: {
      pagination: { pageSize },
    },
    state: {
      sorting,
      columnFilters,
      columnVisibility,
      rowSelection,
      globalFilter: serverState?.search ?? globalFilter,
      ...(pagination ? { pagination: { pageIndex: pagination.pageIndex, pageSize: pagination.pageSize } } : {}),
    },
    manualFiltering: Boolean(serverState),
    manualPagination: Boolean(pagination),
    pageCount: pagination ? pagination.count === null ? -1 : Math.ceil(pagination.count / pagination.pageSize) : undefined,
    enableRowSelection: true,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
  })

  // Reset selection when data identity changes (new schema / reload)
  React.useEffect(() => {
    setRowSelection({})
    if (!serverState) {
      setGlobalFilter("")
      if (!pagination) table.setPageIndex(0)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- only when data ref changes
  }, [data])

  return (
    <div className={cn("flex min-h-0 min-w-0 flex-col", variant === "pane" ? "gap-0 p-0" : "gap-3 p-3", className)} aria-busy={pagination?.loading}>
      <div data-slot="data-table-toolbar" className={cn("flex min-w-0 shrink-0 items-center gap-2", variant === "pane" && "h-10 border-b border-border px-2")}>
        {enableGlobalFilter ? (
          <div className="relative min-w-0 flex-1">
            {variant === "pane" ? <SearchIcon aria-hidden="true" className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" /> : null}
            <Input
              placeholder={variant === "pane" ? undefined : searchPlaceholder}
              aria-label={serverState || variant === "pane" ? "Search records" : undefined}
              value={serverState?.search ?? globalFilter}
              onChange={(e) => serverState ? serverState.onSearchChange(e.target.value) : setGlobalFilter(e.target.value)}
              className={cn("min-w-0", variant === "pane" && "h-7! pl-8! text-xs!")}
            />
          </div>
        ) : null}

        <DropdownMenu>
          <Tooltip>
            <TooltipTrigger asChild>
              <span className="inline-flex">
                <DropdownMenuTrigger asChild>
                  <Button variant="outline" size={variant === "pane" ? "icon-xs" : "icon"} className="shrink-0" aria-label="Columns">
                    <Columns3Icon className="size-4" />
                  </Button>
                </DropdownMenuTrigger>
              </span>
            </TooltipTrigger>
            <TooltipContent side="left">Columns</TooltipContent>
          </Tooltip>
          <DropdownMenuContent align="end">
            {table
              .getAllColumns()
              .filter((column) => column.getCanHide())
              .map((column) => {
                const label =
                  typeof column.columnDef.meta === "object" &&
                  column.columnDef.meta &&
                  "label" in column.columnDef.meta
                    ? String((column.columnDef.meta as { label?: string }).label ?? column.id)
                    : column.id
                return (
                  <DropdownMenuCheckboxItem
                    key={column.id}
                    className="capitalize"
                    checked={column.getIsVisible()}
                    onCheckedChange={(value) => column.toggleVisibility(!!value)}
                  >
                    {label}
                  </DropdownMenuCheckboxItem>
                )
              })}
          </DropdownMenuContent>
        </DropdownMenu>

        {toolbarEnd}
      </div>

      <div data-slot="data-table-viewport" className="relative min-h-0 min-w-0 flex-1">
      <div data-slot="data-table-scroll" className={cn("h-full min-h-0 overflow-auto", variant === "pane" ? "[&>[data-slot=table-container]]:overflow-visible" : "rounded-md border")}>
        <Table>
          <TableHeader className={cn(variant === "pane" && "sticky top-0 z-10 bg-background")}>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id} className="whitespace-nowrap">
                    {header.isPlaceholder
                      ? null
                      : flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() ? "selected" : undefined}
                  className={cn(
                    onRowClick &&
                      "cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
                    isRowActive?.(row.original) && "bg-accent",
                  )}
                  onClick={() => onRowClick?.(row.original)}
                  tabIndex={onRowClick ? 0 : undefined}
                  aria-selected={onRowClick ? Boolean(isRowActive?.(row.original)) : undefined}
                  onKeyDown={(event) => {
                    if (!onRowClick || event.target !== event.currentTarget) return
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault()
                      onRowClick(row.original)
                    }
                  }}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className="max-w-[14rem] truncate align-middle">
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className="h-24 text-center text-muted-foreground"
                >
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      {pagination?.loading ? (
        <div role="status" className="absolute inset-0 z-20 flex items-center justify-center gap-2 bg-background/70 text-sm text-muted-foreground">
          <Spinner aria-hidden="true" />
          <span>Loading records…</span>
        </div>
      ) : null}
      </div>

      <div data-slot="data-table-pagination" className={cn("flex shrink-0 items-center justify-between gap-2", variant === "pane" && "border-t border-border px-2 py-1.5")}>
        {showSelectionSummary ? (
          <div className="text-sm text-muted-foreground">
            {table.getFilteredSelectedRowModel().rows.length} of{" "}
            {table.getFilteredRowModel().rows.length} row(s) selected.
          </div>
        ) : (
          <div className="text-sm text-muted-foreground">{pagination ? pagination.count === null ? "" : `${pagination.count} records` : null}</div>
        )}
        <div className="flex items-center gap-2">
          <Button
            type="button"
            variant="outline"
            size={variant === "pane" ? "xs" : "sm"}
            onClick={() => pagination ? pagination.onPageChange(pagination.pageIndex - 1) : table.previousPage()}
            disabled={!table.getCanPreviousPage() || Boolean(pagination?.loading)}
          >
            Previous
          </Button>
          <span className="text-sm text-muted-foreground tabular-nums">
            {table.getState().pagination.pageIndex + 1}{pagination?.count === null ? "" : ` / ${Math.max(table.getPageCount(), 1)}`}
          </span>
          <Button
            type="button"
            variant="outline"
            size={variant === "pane" ? "xs" : "sm"}
            onClick={() => pagination ? pagination.onPageChange(pagination.pageIndex + 1) : table.nextPage()}
            disabled={(pagination?.count === null ? !pagination.hasMore : !table.getCanNextPage()) || Boolean(pagination?.loading)}
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  )
}
