import { useLayoutEffect, useMemo } from "react"
import { Controller, useForm } from "react-hook-form"
import { Button } from "@/components/ui/button"
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldTitle,
} from "@/components/ui/field"
import {
  groupRecordValidationIssues,
  recordValidationErrorDetails,
} from "@/lib/record-validation-error"
import { cn } from "@/lib/utils"
import { normalizeFormField } from "../../../../../mapsvg/FormBuilder/FieldDefinitions"
import { complexSchemaFieldControls } from "../complex-fields/controlRegistry"
import { locationSchemaFieldControls } from "../location-field/controlRegistry"
import { simpleSchemaFieldControls } from "./controlRegistry"
import type { SchemaFieldControlRegistry, SchemaFormRecord, SchemaFormSchema } from "./types"
import { nextSchemaFormRecord, schemaFields } from "./value"
import { createSchemaFormValidation } from "./validation"

const EMPTY_RECORD: SchemaFormRecord = {}

export type SchemaFormProps = {
  schema: SchemaFormSchema
  value?: SchemaFormRecord
  onChange?: (value: SchemaFormRecord) => void
  onSubmit?: (value: SchemaFormRecord) => void | Promise<void>
  fieldControls?: Partial<SchemaFieldControlRegistry>
  controlContext?: Record<string, unknown>
  disabled?: boolean
  mode?: "create" | "edit"
  submitLabel?: string
  variant?: "default" | "pane"
  className?: string
}

export function SchemaForm({
  schema,
  value,
  onChange,
  onSubmit,
  fieldControls,
  controlContext,
  disabled = false,
  mode = "edit",
  submitLabel = "Save",
  variant = "default",
  className,
}: SchemaFormProps) {
  const fields = useMemo(
    () => schemaFields(schema).map((field) => normalizeFormField(field)),
    [schema],
  )
  const controls = useMemo(
    () => ({
      ...simpleSchemaFieldControls,
      ...complexSchemaFieldControls,
      ...locationSchemaFieldControls,
      ...(fieldControls ?? {}),
    }),
    [fieldControls],
  )
  const record = value ?? EMPTY_RECORD
  const recordOwner = useMemo(() => ({}), [record])
  const validation = useMemo(
    () => createSchemaFormValidation(Array.isArray(schema) ? null : (schema.zodSettings ?? null)),
    [schema],
  )
  const form = useForm<SchemaFormRecord>({
    defaultValues: record,
    resolver: validation?.resolver,
    mode: "onSubmit",
    reValidateMode: "onChange",
  })

  useLayoutEffect(() => {
    form.reset(record)
  }, [form, record])

  const emitChange = (name: string, nextValue: unknown) => {
    onChange?.(
      nextSchemaFormRecord(
        {
          ...record,
          ...form.getValues(),
        },
        name,
        nextValue,
      ),
    )
  }

  const handleSubmit = form.handleSubmit(async (formRecord) => {
    form.clearErrors()
    try {
      await onSubmit?.({
        ...record,
        ...formRecord,
      })
    } catch (error) {
      const details = recordValidationErrorDetails(error)
      if (!details) throw error

      const grouped = groupRecordValidationIssues(details.issues)
      const fieldNames = new Set(fields.map((field) => String(field.name ?? "")).filter(Boolean))
      const rootMessages = [...grouped.root]

      for (const [name, messages] of grouped.fields) {
        if (!fieldNames.has(name)) {
          rootMessages.push(`${name}: ${messages.join("; ")}`)
          continue
        }
        form.setError(name, {
          type: "server",
          message: messages.join("; "),
        })
      }

      if (rootMessages.length > 0) {
        form.setError("root", {
          type: "server",
          message: [...new Set(rootMessages)].join("; "),
        })
      }
    }
  })

  const formErrors = form.formState.errors as Record<string, { message?: unknown } | undefined>
  const formLevelError =
    typeof formErrors[""]?.message === "string"
      ? formErrors[""]?.message
      : typeof formErrors.root?.message === "string"
        ? formErrors.root.message
        : null

  return (
    <form
      data-slot="schema-form"
      className={cn(variant === "pane" ? "flex min-h-0 flex-1 flex-col overflow-hidden" : "grid gap-6", className)}
      onSubmit={handleSubmit}
    >
      <div
        data-slot="schema-form-fields"
        className={cn("grid content-start gap-6", variant === "pane" && "min-h-0 flex-1 overflow-auto p-3")}
      >
        {validation?.configurationError ? (
          <div
            role="alert"
            className="rounded-md border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive"
          >
            Validation configuration error: {validation.configurationError}
          </div>
        ) : null}
        <FieldGroup>
          {fields.map((field, index) => {
            if (field.visible === false) {
              return null
            }

            const name = typeof field.name === "string" ? field.name : ""
            const Control = controls[field.type]
            const key = name || `${field.type}-${index}`

            if (!name || !Control) {
              return (
                <Field key={key} data-schema-field-unsupported={field.type}>
                  <FieldContent>
                    <FieldTitle>{field.label || field.name || field.type}</FieldTitle>
                    <FieldDescription>
                      {!name
                        ? "This schema field has no name and cannot be edited."
                        : `Field type “${field.type}” is not available in the React form renderer yet.`}
                    </FieldDescription>
                  </FieldContent>
                </Field>
              )
            }

            const fieldDisabled =
              disabled || field.readonly === true || (field.type === "id" && mode !== "create")
            return (
              <Controller
                key={key}
                name={name}
                control={form.control}
                render={({ field: controlled, fieldState }) => (
                  <Field data-invalid={fieldState.invalid || undefined}>
                    <FieldContent>
                      <FieldTitle>{field.label || name}</FieldTitle>
                      <Control
                        field={field}
                        value={controlled.value}
                        disabled={fieldDisabled}
                        context={controlContext}
                        recordOwner={recordOwner}
                        onChange={(nextValue) => {
                          form.clearErrors(name)
                          controlled.onChange(nextValue)
                          emitChange(name, nextValue)
                        }}
                      />
                      {field.help ? <FieldDescription>{String(field.help)}</FieldDescription> : null}
                      <FieldError errors={fieldState.error ? [fieldState.error] : undefined} />
                    </FieldContent>
                  </Field>
                )}
              />
            )
          })}
        </FieldGroup>

        {formLevelError ? (
          <div
            role="alert"
            className="rounded-md border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive"
          >
            {formLevelError}
          </div>
        ) : null}
      </div>

      {onSubmit ? (
        <div
          data-slot="schema-form-footer"
          className={cn("flex justify-end", variant === "pane" && "shrink-0 border-t border-border bg-background px-3 py-2")}
        >
          <Button
            type="submit"
            disabled={
              disabled || form.formState.isSubmitting || Boolean(validation?.configurationError)
            }
          >
            {submitLabel}
          </Button>
        </div>
      ) : null}
    </form>
  )
}
