import type { RuleGroupType } from "react-querybuilder"
import {
  prismaQueryFromBuilder,
  queryBuilderFieldsForSchema,
} from "@/components/data/savedDataQueries"
import type { DataSchema, GlobalQueryDraft, GlobalSavedQuery } from "@/lib/mapsvg-api"

export function copyQueryValue<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T
}

function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value)
}

function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`
  if (record(value)) {
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`)
      .join(",")}}`
  }
  return JSON.stringify(value) ?? "undefined"
}

export function queryContentKey(value: unknown): string {
  return canonical(value)
}

export function savedQueryContentKey(query: GlobalSavedQuery | null): string {
  return queryContentKey(query)
}

// Query Builder may add UI identities on mount; they do not author a predicate.
function builderContent(builder: RuleGroupType): unknown {
  const { id: _id, ...content } = builder
  return {
    ...content,
    rules: builder.rules.map((rule) => {
      if ("rules" in rule) return builderContent(rule)
      const { id: _ruleId, ...ruleContent } = rule
      return ruleContent
    }),
  }
}

function schemaReferences(schema: DataSchema) {
  const fields = [...(schema.fields ?? [])]
  if (!fields.some((field) => field.name === "id")) {
    const primary =
      fields.find((field) => field.name === schema.primaryKeyField) ??
      fields.find((field) => field.type === "id")
    if (primary) fields.push({ ...primary, name: "id" })
  }
  const supported = queryBuilderFieldsForSchema({ ...schema, fields })
  return {
    names: new Set(fields.map((field) => field.name)),
    operators: new Map(
      supported.map((field) => [
        field.name,
        new Set((field.operators as Array<{ name: string }>).map((operator) => operator.name)),
      ]),
    ),
  }
}

function referenceError(field: string): Error {
  return new Error(
    `The chosen collection cannot use field “${field}”. Restore the original collection or repair this query's references.`,
  )
}

function validateBuilder(builder: RuleGroupType, schema: DataSchema): void {
  const { operators } = schemaReferences(schema)
  let nodes = 0
  const visit = (group: RuleGroupType, depth: number) => {
    if (++nodes > 500 || depth > 24) throw new Error("The filter is too complex to edit here.")
    if (!["and", "or"].includes(group.combinator) || !Array.isArray(group.rules)) {
      throw new Error(
        "This filter uses an unsupported builder structure. Restore its original definition before editing filters.",
      )
    }
    for (const rule of group.rules) {
      if ("rules" in rule) {
        visit(rule, depth + 1)
        continue
      }
      const allowed = operators.get(rule.field)
      if (!allowed) throw referenceError(rule.field)
      if (!allowed.has(rule.operator) || rule.valueSource === "field") {
        throw new Error(
          `Field “${rule.field}” cannot use operator “${rule.operator}” in this collection. Repair the filter before saving.`,
        )
      }
      if (rule.value === undefined)
        throw new Error(`Enter a filter value for “${rule.field}” before saving.`)
      if (++nodes > 500) throw new Error("The filter is too complex to edit here.")
    }
  }
  visit(builder, 0)
}

const predicateOperators: Record<string, string> = {
  equals: "=",
  not: "!=",
  lt: "<",
  lte: "<=",
  gt: ">",
  gte: ">=",
  contains: "contains",
  startsWith: "beginsWith",
  endsWith: "endsWith",
  in: "in",
  notIn: "notIn",
}

/** Reference checks only. The server remains the authority for types, limits and execution. */
function validateRetargetedInput(input: GlobalSavedQuery["input"], schema: DataSchema): void {
  const { names, operators } = schemaReferences(schema)
  const requireName = (name: string) => {
    if (!names.has(name)) throw referenceError(name)
  }
  const validatePredicate = (where: unknown, depth = 0): void => {
    if (depth > 24 || !record(where)) {
      throw new Error(
        "The saved predicate cannot be verified for a different collection. Keep its original collection.",
      )
    }
    for (const [name, value] of Object.entries(where)) {
      if (["AND", "OR", "NOT"].includes(name)) {
        for (const child of Array.isArray(value) ? value : [value])
          validatePredicate(child, depth + 1)
        continue
      }
      requireName(name)
      const allowed = operators.get(name)
      if (!allowed) throw referenceError(name)
      if (!record(value)) {
        if (!allowed.has("=")) throw referenceError(name)
        continue
      }
      const validateOperators = (conditions: Record<string, unknown>) => {
        for (const [operator, operand] of Object.entries(conditions)) {
          if (!allowed.has(predicateOperators[operator])) {
            throw new Error(
              `The saved operator “${operator}” for “${name}” is unavailable in the chosen collection.`,
            )
          }
          if (operator === "not" && record(operand)) validateOperators(operand)
        }
      }
      validateOperators(value)
    }
  }
  for (const key of Object.keys(input)) {
    if (!["where", "select", "orderBy", "skip", "take"].includes(key)) {
      throw new Error(
        `Saved input “${key}” cannot be verified for a different collection. Keep its original collection.`,
      )
    }
  }
  if (input.where !== undefined) validatePredicate(input.where)
  if (input.select !== undefined) {
    const selection: unknown = input.select
    if (!Array.isArray(selection) && !record(selection))
      throw new Error("The saved selection cannot be verified for this collection.")
    for (const name of Array.isArray(selection) ? selection : Object.keys(selection)) {
      if (typeof name !== "string")
        throw new Error("The saved selection contains an unsupported field reference.")
      requireName(name)
    }
  }
  if (input.orderBy !== undefined) {
    for (const order of Array.isArray(input.orderBy) ? input.orderBy : [input.orderBy]) {
      if (!record(order))
        throw new Error("The saved ordering cannot be verified for this collection.")
      for (const [name, direction] of Object.entries(order)) {
        requireName(name)
        if (
          !operators.has(name) ||
          typeof direction !== "string" ||
          !["asc", "desc"].includes(direction.toLowerCase())
        ) {
          throw new Error(
            `The saved ordering for “${name}” is unavailable in the chosen collection.`,
          )
        }
      }
    }
  }
}

export function globalQueryDraft({
  query,
  name,
  schema,
  folderId,
  builder,
  originalSchema,
  orderBy,
  take,
}: {
  query: GlobalSavedQuery | null
  name: string
  schema: DataSchema
  folderId: number | null
  builder: RuleGroupType
  originalSchema?: DataSchema | null
  orderBy?: Array<Record<string, "asc" | "desc">>
  take?: number | null
}): GlobalQueryDraft {
  const savedName = query?.name ?? name
  if (!/^[a-z][a-zA-Z0-9]{0,119}$/.test(savedName))
    throw new Error("Use a unique camelCase system name.")
  const builderChanged =
    !query || canonical(builderContent(builder)) !== canonical(builderContent(query.builder))
  const collectionChanged = !!query && String(schema.id) !== String(query.schemaId)
  let input = query ? copyQueryValue(query.input) : prismaQueryFromBuilder(builder)
  if (builderChanged || collectionChanged) validateBuilder(builder, schema)
  if (query && builderChanged) {
    const source = originalSchema ?? (String(schema.id) === String(query.schemaId) ? schema : null)
    if (!source) {
      throw new Error(
        "The original collection is unavailable. Restore its Schema before changing saved filters.",
      )
    }
    validateBuilder(query.builder, source)
    const originalWhere = prismaQueryFromBuilder(query.builder).where ?? {}
    if (canonical(originalWhere) !== canonical(query.input.where ?? {})) {
      throw new Error(
        "The saved predicate is not fully represented by these filters. Undo filter changes to save metadata only, or edit the original Query definition before changing filters.",
      )
    }
    input = { ...input, ...prismaQueryFromBuilder(builder) }
  }
  if (orderBy !== undefined) {
    if (orderBy.length) input.orderBy = copyQueryValue(orderBy)
    else delete input.orderBy
  }
  if (take === null) {
    delete input.take
    delete input.skip
  } else if (take !== undefined) {
    if (!Number.isInteger(take) || take < 1 || take > 250) throw new Error("Items per page must be an integer from 1 to 250.")
    input.take = take
  }
  if (collectionChanged) validateRetargetedInput(input, schema)
  return copyQueryValue({
    id: query?.id,
    name: savedName,
    schemaId: Number(schema.id),
    folderId,
    builder,
    input,
  })
}
