import { useLayoutEffect, useState } from "react"
import { ImagePlus, Loader2, Search, X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { useDragSort } from "@/lib/use-drag-sort"
import { cn } from "@/lib/utils"
import { useControlRequest } from "../schema-form/useControlRequest"
import type { SchemaFieldControlProps } from "../schema-form/types"
import { adaptersFromContext, type MapSvgPost } from "./adapters"
import { imageValue, moveArrayItem } from "./value"

export function ImageFieldControl(props: SchemaFieldControlProps) {
  const { field, value, disabled, context, onChange } = props
  const media = adaptersFromContext(context).media
  const { owner, begin } = useControlRequest(props, media)
  const images = imageValue(value)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")
  const dragSort = useDragSort<number>((from, to) => {
    if (disabled || busy) return
    const next = moveArrayItem(images, from, to)
    if (next !== images) onChange(next)
  })

  useLayoutEffect(() => {
    dragSort.cancel()
  }, [owner, busy, dragSort.cancel])

  useLayoutEffect(() => {
    setBusy(false)
    setError("")
  }, [owner])

  const browse = async () => {
    if (!media || disabled || busy) return
    const ownsRequest = begin()
    setBusy(true)
    setError("")
    try {
      const picked = await media.pickImages()
      if (ownsRequest() && picked.length) {
        onChange(images.concat(picked))
      }
    } catch (err) {
      if (ownsRequest())
        setError(err instanceof Error ? err.message : "Unable to open media library.")
    } finally {
      if (ownsRequest()) setBusy(false)
    }
  }

  return (
    <div className="grid gap-3">
      <div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          disabled={disabled || busy || !media}
          onClick={browse}
        >
          {busy ? <Loader2 className="animate-spin" /> : <ImagePlus />}
          {field.button_text || "Browse..."}
        </Button>
      </div>
      {images.length ? (
        <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
          {images.map((image, index) => {
            const src =
              (typeof image.thumbnail === "string" && image.thumbnail) ||
              (typeof image.medium === "string" && image.medium) ||
              (typeof image.full === "string" && image.full) ||
              ""
            return (
              <div
                key={`${src}-${index}`}
                data-slot="image-preview"
                {...(!disabled && !busy ? dragSort.itemProps(index) : {})}
                className={cn(
                  "group/image relative overflow-hidden rounded-md border",
                  !disabled && !busy && "cursor-grab active:cursor-grabbing",
                  dragSort.dragged === index && "opacity-50",
                  dragSort.target === index && dragSort.dragged !== index && "ring-2 ring-ring",
                )}
              >
                <div className="aspect-video bg-muted">
                  {src ? <img src={src} alt="" draggable={false} className="h-full w-full object-cover" /> : null}
                </div>
                <Button
                  type="button"
                  variant="outline"
                  size="icon-xs"
                  className="absolute right-1 top-1 rounded-full bg-background/90 opacity-0 shadow-sm group-hover/image:opacity-100 group-focus-within/image:opacity-100 [@media(hover:none)]:opacity-100"
                  disabled={disabled || busy}
                  aria-label="Remove image"
                  onClick={() => onChange(images.filter((_, i) => i !== index))}
                >
                  <X />
                </Button>
              </div>
            )
          })}
        </div>
      ) : (
        <div className="text-sm text-muted-foreground">No images selected.</div>
      )}
      {!media ? (
        <div className="text-xs text-muted-foreground">Media picker adapter is not connected.</div>
      ) : null}
      {error ? <div className="text-xs text-destructive">{error}</div> : null}
    </div>
  )
}
export function PostFieldControl(props: SchemaFieldControlProps) {
  const { field, value, disabled, context, onChange } = props
  const posts = adaptersFromContext(context).posts
  const { owner, begin, cancel } = useControlRequest(props, posts)
  const post = value && typeof value === "object" ? (value as MapSvgPost) : undefined
  const [query, setQuery] = useState("")
  const [results, setResults] = useState<MapSvgPost[]>([])
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")

  useLayoutEffect(() => {
    setQuery("")
    setResults([])
    setBusy(false)
    setError("")
  }, [owner])

  const search = async () => {
    if (!posts || !query.trim() || disabled || busy) return
    const ownsRequest = begin()
    setBusy(true)
    setError("")
    try {
      const found = await posts.searchPosts(
        typeof field.post_type === "string" && field.post_type ? field.post_type : "post",
        query,
      )
      if (ownsRequest()) setResults(found)
    } catch (err) {
      if (ownsRequest()) setError(err instanceof Error ? err.message : "Post search failed.")
    } finally {
      if (ownsRequest()) setBusy(false)
    }
  }

  return (
    <div className="grid gap-3">
      {post ? (
        <div className="flex items-start justify-between gap-3 rounded-md border p-3">
          <div className="min-w-0">
            <div className="truncate text-sm font-medium">{post.post_title}</div>
            <div className="text-xs text-muted-foreground">post.id: {post.id}</div>
            {post.url ? (
              <a
                className="block truncate text-xs underline"
                href={post.url}
                target="_blank"
                rel="noreferrer"
              >
                {post.url}
              </a>
            ) : null}
          </div>
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            disabled={disabled}
            aria-label="Clear post"
            onClick={() => onChange(null)}
          >
            <X />
          </Button>
        </div>
      ) : null}
      <div className="flex gap-2">
        <Input
          value={query}
          disabled={disabled || !posts}
          placeholder="Search post by title"
          onChange={(event) => {
            cancel()
            setBusy(false)
            setResults([])
            setQuery(event.target.value)
          }}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault()
              void search()
            }
          }}
        />
        <Button
          type="button"
          variant="outline"
          disabled={disabled || !posts || busy || !query.trim()}
          onClick={() => void search()}
        >
          {busy ? <Loader2 className="animate-spin" /> : <Search />}
          Search
        </Button>
      </div>

      {results.length ? (
        <div className="grid max-h-52 gap-1 overflow-auto rounded-md border p-1">
          {results.map((result) => (
            <button
              key={result.id}
              type="button"
              className="rounded px-2 py-2 text-left text-sm hover:bg-accent"
              disabled={disabled}
              onClick={() => {
                onChange(result)
                setResults([])
                setQuery("")
              }}
            >
              <div className="font-medium">{result.post_title}</div>
              <div className="text-xs text-muted-foreground">#{result.id}</div>
            </button>
          ))}
        </div>
      ) : null}
      {!posts ? (
        <div className="text-xs text-muted-foreground">Post search adapter is not connected.</div>
      ) : null}
      {error ? <div className="text-xs text-destructive">{error}</div> : null}
    </div>
  )
}
export { RegionFieldControl } from "./RegionFieldControl"
