import { useId, useLayoutEffect, useRef, useState } from "react"
import { CalendarIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { ColorInput } from "@/components/settings-form/ColorInput"
import { readRecordDate, writeRecordDate } from "./date-value"
import type { SchemaFieldControlProps } from "./types"

/** Close an open picker before a replacement record becomes interactive. */
function useRecordPickerKey(owner: object | undefined) {
  const previous = useRef(owner)
  const [key, setKey] = useState(0)
  useLayoutEffect(() => {
    if (previous.current !== owner) {
      previous.current = owner
      setKey(value => value + 1)
    }
  }, [owner])
  return key
}

function RecordDateInput({ field, value, disabled, onChange }: SchemaFieldControlProps) {
  const [open, setOpen] = useState(false)
  const text = value == null ? "" : String(value)
  const label = String(field.label || field.name || "Date")
  const parsed = readRecordDate(text, field.language)
  return <div className="flex min-w-0 items-center gap-2">
    <Input value={text} aria-label={label} placeholder={field.placeholder ?? parsed.format} readOnly={disabled}
      onChange={event => { if (!disabled) onChange(event.target.value) }} />
    <Popover open={!disabled && open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button type="button" variant="outline" size="icon" disabled={disabled} aria-label={`Choose ${label} date`}><CalendarIcon /></Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto p-0" aria-label={`${label} calendar`}>
        <Calendar mode="single" selected={parsed.date} defaultMonth={parsed.date} disabled={disabled}
          onSelect={date => {
            if (disabled) return
            onChange(date ? writeRecordDate(date, parsed.format) : "")
            setOpen(false)
          }} />
        {text ? <div className="border-t p-2"><Button type="button" variant="ghost" size="sm" onClick={() => {
          if (!disabled) onChange("")
          setOpen(false)
        }}>Clear date</Button></div> : null}
      </PopoverContent>
    </Popover>
  </div>
}

export function DateControl(props: SchemaFieldControlProps) {
  return <RecordDateInput key={`${useRecordPickerKey(props.recordOwner)}:${props.disabled}`} {...props} />
}

export function ColorControl({ field, value, disabled, onChange, recordOwner }: SchemaFieldControlProps) {
  const id = useId()
  return <ColorInput key={`${useRecordPickerKey(recordOwner)}:${disabled}`} id={id} label={String(field.label || field.name || "Color")}
    value={value == null ? "" : String(value)} disabled={disabled} placeholder={field.placeholder}
    onChange={next => { if (!disabled) onChange(next) }} />
}
