import type { MapSvgImage, MapSvgRegionOption, MapSvgRegionRef } from "./adapters"

export function imageValue(value: unknown): MapSvgImage[] {
  return Array.isArray(value)
    ? value.filter((item): item is MapSvgImage => Boolean(item && typeof item === "object"))
    : []
}

export function moveArrayItem<T>(items: T[], from: number, to: number): T[] {
  if (from === to || from < 0 || to < 0 || from >= items.length || to >= items.length) {
    return items
  }

  const next = [...items]
  const [item] = next.splice(from, 1)
  next.splice(to, 0, item)
  return next
}

export function regionRefs(value: unknown): MapSvgRegionRef[] {
  return Array.isArray(value)
    ? value.filter((item): item is MapSvgRegionRef =>
        Boolean(item && typeof item === "object" && "id" in item),
      )
    : []
}

export function selectedRegionIds(value: unknown, tableName: string): string[] {
  return regionRefs(value)
    .filter((region) => region.tableName === tableName)
    .map((region) => String(region.id))
}

export function mergeRegionSelection(
  value: unknown,
  tableName: string,
  available: MapSvgRegionOption[],
  selectedIds: Iterable<string>,
): MapSvgRegionRef[] {
  const selected = new Set(selectedIds)
  const foreign = regionRefs(value).filter((region) => region.tableName !== tableName)

  const current = available
    .filter((region) => selected.has(String(region.id)))
    .map((region) => ({
      id: String(region.id),
      title: region.title || String(region.id),
      tableName,
    }))

  return current.concat(foreign)
}
