import type { ReactNode } from "react"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { cn } from "@/lib/utils"

const EMPTY_VALUE = "__mapsvg_empty_value__"

export type FormBuilderSelectOption = {
  value: string
  label: ReactNode
  disabled?: boolean
}

export type FormBuilderSelectGroup = {
  label: string
  options: FormBuilderSelectOption[]
}

type Props = {
  value: string
  onValueChange: (value: string) => void
  options?: FormBuilderSelectOption[]
  groups?: FormBuilderSelectGroup[]
  emptyLabel?: string
  placeholder?: string
  disabled?: boolean
  className?: string
  id?: string
  "aria-label"?: string
  title?: string
  "data-testid"?: string
}
function SelectOptions({ options }: { options: FormBuilderSelectOption[] }) {
  return options.map((option) => (
    <SelectItem
      key={option.value}
      value={option.value}
      data-option-value={option.value}
      disabled={option.disabled}
    >
      {option.label}
    </SelectItem>
  ))
}

export function FormBuilderSelect({
  value,
  onValueChange,
  options = [],
  groups = [],
  emptyLabel,
  placeholder,
  disabled,
  className,
  ...triggerProps
}: Props) {
  const values = new Set(
    [...options, ...groups.flatMap((group) => group.options)].map((option) => option.value),
  )
  let emptyToken = EMPTY_VALUE
  while (values.has(emptyToken)) emptyToken += "_"
  const normalizedValue = value === "" && emptyLabel ? emptyToken : value

  return (
    <Select
      value={normalizedValue || undefined}
      disabled={disabled}
      onValueChange={(next) => {
        if (!disabled) onValueChange(next === emptyToken ? "" : next)
      }}
    >
      <SelectTrigger {...triggerProps} className={cn("w-full", className)}>
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent position="popper" align="start">
        {emptyLabel ? (
          <SelectItem value={emptyToken} data-option-value="">
            {emptyLabel}
          </SelectItem>
        ) : null}
        {groups.length ? (
          groups.map((group) => (
            <SelectGroup key={group.label}>
              <SelectLabel>{group.label}</SelectLabel>
              <SelectOptions options={group.options} />
            </SelectGroup>
          ))
        ) : (
          <SelectOptions options={options} />
        )}
      </SelectContent>
    </Select>
  )
}
