import { useEffect, useState } from "react"
import { Button } from "@/components/ui/button"
import { Field, FieldContent, FieldDescription, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { FormBuilderChoice } from "../FormBuilderChoice"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import { Trash2 } from "lucide-react"
import {
  buildFieldOptionsPatch,
  isFieldNameLocked,
  parseFieldOptions,
  sanitizeFieldName,
  serializeFieldOptions,
} from "./model"
import type { SchemaFieldSettingsProps } from "./types"
import { ValidationSettings } from "./ValidationSettings"

function TextSetting({
  label,
  value,
  disabled,
  description,
  onChange,
}: {
  label: string
  value: unknown
  disabled?: boolean
  description?: string
  onChange: (value: string) => void
}) {
  return (
    <Field>
      <FieldContent>
        <FieldLabel>{label}</FieldLabel>
        <Input
          value={value == null ? "" : String(value)}
          disabled={disabled}
          onChange={(event) => onChange(event.target.value)}
        />
        {description ? <FieldDescription>{description}</FieldDescription> : null}
      </FieldContent>
    </Field>
  )
}

function SwitchSetting({
  label,
  checked,
  description,
  onChange,
}: {
  label: string
  checked: boolean
  description?: string
  onChange: (checked: boolean) => void
}) {
  return (
    <Field orientation="horizontal">
      <FieldContent>
        <FieldLabel>{label}</FieldLabel>
        {description ? <FieldDescription>{description}</FieldDescription> : null}
      </FieldContent>
      <Switch checked={checked} onCheckedChange={onChange} />
    </Field>
  )
}

function OptionsSetting({ field, onPatch }: Pick<SchemaFieldSettingsProps, "field" | "onPatch">) {
  const [raw, setRaw] = useState(() => serializeFieldOptions(field))

  useEffect(() => {
    setRaw(serializeFieldOptions(field))
  }, [field])

  return (
    <Field>
      <FieldContent>
        <FieldLabel>Options</FieldLabel>
        <Textarea
          rows={6}
          value={raw}
          placeholder={"Label:value\nAnother:another"}
          onChange={(event) => setRaw(event.target.value)}
          onBlur={() => onPatch(buildFieldOptionsPatch(field, parseFieldOptions(raw)))}
        />
        <FieldDescription>One option per line: label:value</FieldDescription>
      </FieldContent>
    </Field>
  )
}

function CommonSettings({
  field,
  fieldIndex,
  errors,
  validation,
  onPatch,
  onRemove,
  children,
}: SchemaFieldSettingsProps & { children?: React.ReactNode }) {
  const nameLocked = isFieldNameLocked(field)
  const fieldErrors = errors.filter((error) => error.index === fieldIndex)

  return (
    <div className="grid gap-5">
      <div className="grid gap-4">
        <TextSetting label="Label" value={field.label} onChange={(label) => onPatch({ label })} />
        <TextSetting
          label="Name"
          value={field.name}
          disabled={nameLocked}
          onChange={(name) => onPatch({ name: sanitizeFieldName(name) })}
        />
        <Field>
          <FieldContent>
            <FieldLabel>Help</FieldLabel>
            <Textarea
              value={field.help == null ? "" : String(field.help)}
              onChange={(event) => onPatch({ help: event.target.value })}
            />
          </FieldContent>
        </Field>
      </div>

      {children}

      {validation ? (
        <ValidationSettings
          field={field}
          zodSettings={validation.zodSettings}
          onChange={validation.onChange}
        />
      ) : null}

      {fieldErrors.length ? (
        <div className="grid gap-1 text-sm text-destructive">
          {fieldErrors.map((error, index) => (
            <div key={`${error.message}-${index}`}>{error.message}</div>
          ))}
        </div>
      ) : null}

      <div className="border-t pt-4">
        <Button
          type="button"
          variant="destructive"
          size="sm"
          disabled={field.protected === true}
          onClick={onRemove}
        >
          <Trash2 />
          Remove field
        </Button>
        {field.protected === true ? (
          <FieldDescription className="mt-2">
            This field is protected by the schema and cannot be removed.
          </FieldDescription>
        ) : null}
      </div>
    </div>
  )
}

function SearchableSettings({
  field,
  onPatch,
  showSearchType = false,
}: Pick<SchemaFieldSettingsProps, "field" | "onPatch"> & {
  showSearchType?: boolean
}) {
  return (
    <div className="grid gap-4">
      <SwitchSetting
        label="Searchable"
        checked={field.searchable === true}
        description="Include this field in text search."
        onChange={(searchable) => onPatch({ searchable })}
      />
      {showSearchType ? (
        <Field>
          <FieldContent>
            <FieldLabel>Search type</FieldLabel>
            <FormBuilderChoice
              value={field.searchType == null ? "fulltext" : String(field.searchType)}
              onValueChange={(searchType) => onPatch({ searchType })}
              options={[
                { value: "fulltext", label: "Fulltext" },
                { value: "exact", label: "Exact match" },
                { value: "like", label: "LIKE prefix" },
              ]}
            />
          </FieldContent>
        </Field>
      ) : null}
    </div>
  )
}

function PlainFieldSettings(props: SchemaFieldSettingsProps) {
  return <CommonSettings {...props} />
}

function TextFieldSettings(props: SchemaFieldSettingsProps) {
  return (
    <CommonSettings {...props}>
      <SearchableSettings field={props.field} onPatch={props.onPatch} showSearchType />
    </CommonSettings>
  )
}

function TextareaFieldSettings(props: SchemaFieldSettingsProps) {
  return (
    <CommonSettings {...props}>
      <SwitchSetting
        label="HTML highlight"
        checked={props.field.html === true}
        description="Use the HTML code editor when editing this field."
        onChange={(html) => props.onPatch({ html })}
      />
      <SearchableSettings field={props.field} onPatch={props.onPatch} />
    </CommonSettings>
  )
}
function CheckboxFieldSettings(props: SchemaFieldSettingsProps) {
  return (
    <CommonSettings {...props}>
      <TextSetting
        label="Checkbox label"
        value={props.field.checkboxLabel}
        onChange={(checkboxLabel) => props.onPatch({ checkboxLabel })}
      />
      <SwitchSetting
        label="Show as switch"
        checked={props.field.showAsSwitch !== false}
        onChange={(showAsSwitch) => props.onPatch({ showAsSwitch })}
      />
    </CommonSettings>
  )
}

function OptionsFieldSettings(
  props: SchemaFieldSettingsProps & {
    searchable?: boolean
    multiselect?: boolean
    placeholderLabel?: string
  },
) {
  return (
    <CommonSettings {...props}>
      {props.placeholderLabel ? (
        <TextSetting
          label={props.placeholderLabel}
          value={props.field.placeholder}
          description={props.field.type === "radio" ? "An empty-value option that shows all results when selected." : undefined}
          onChange={(placeholder) => props.onPatch({ placeholder })}
        />
      ) : null}
      <OptionsSetting key={props.fieldIndex} field={props.field} onPatch={props.onPatch} />
      {props.multiselect ? (
        <SwitchSetting
          label="Multiselect"
          checked={props.field.multiselect === true}
          onChange={(multiselect) =>
            props.onPatch({
              multiselect,
              db_type: multiselect ? "text" : "varchar(255)",
            })
          }
        />
      ) : null}
      {props.searchable ? <SearchableSettings field={props.field} onPatch={props.onPatch} /> : null}
    </CommonSettings>
  )
}

function CheckboxesFieldSettings(props: SchemaFieldSettingsProps) {
  return <OptionsFieldSettings {...props} />
}

function RadioFieldSettings(props: SchemaFieldSettingsProps) {
  return <OptionsFieldSettings {...props} searchable />
}

function SelectFieldSettings(props: SchemaFieldSettingsProps) {
  return <OptionsFieldSettings {...props} searchable multiselect />
}
function StatusFieldSettings(props: SchemaFieldSettingsProps) {
  return (
    <CommonSettings {...props}>
      <OptionsSetting key={props.fieldIndex} field={props.field} onPatch={props.onPatch} />
      <FieldDescription>
        Region colors and disabled state are configured in Region component settings.
      </FieldDescription>
    </CommonSettings>
  )
}

function DateFieldSettings(props: SchemaFieldSettingsProps) {
  return (
    <CommonSettings {...props}>
      <TextSetting
        label="Language"
        value={props.field.language}
        description="Datepicker language code used by the legacy frontend renderer."
        onChange={(language) => props.onPatch({ language })}
      />
    </CommonSettings>
  )
}

function TitleFieldSettings(props: SchemaFieldSettingsProps) {
  return (
    <CommonSettings {...props}>
      <SearchableSettings field={props.field} onPatch={props.onPatch} showSearchType />
    </CommonSettings>
  )
}

export {
  CommonSettings,
  OptionsFieldSettings,
  SearchableSettings,
  SwitchSetting,
  TextSetting,
  CheckboxFieldSettings,
  CheckboxesFieldSettings,
  DateFieldSettings,
  PlainFieldSettings,
  RadioFieldSettings,
  SelectFieldSettings,
  StatusFieldSettings,
  TextareaFieldSettings,
  TextFieldSettings,
  TitleFieldSettings,
}
