import { formatQuery, type Field, type RuleGroupType } from "react-querybuilder"
import type { MapsvgMapInstance } from "@/lib/mapsvg-client"
import { patchLiveMapOptions, readLiveDatabase } from "@/lib/live-map-options"
import type { DataSourceRole } from "@/components/data/dataNav"
import type { DataSchema, SchemaField } from "@/lib/mapsvg-api"

export type PrismaDataQuery = {
  where?: Record<string, unknown>
  select?: string[]
  orderBy?: Record<string, "asc" | "desc"> | Array<Record<string, "asc" | "desc">>
  take?: number
  skip?: number
}

export type SavedDataQuery = {
  id: string
  name: string
  schemaId: string
  sourceRole: DataSourceRole
  builder: RuleGroupType
  query: PrismaDataQuery
}

export const EMPTY_QUERY_BUILDER: RuleGroupType = {
  combinator: "and",
  rules: [],
}

export const PLASMA_QUERY_OPERATORS = [
  { name: "=", label: "equals" },
  { name: "!=", label: "does not equal" },
  { name: "<", label: "less than" },
  { name: "<=", label: "less than or equal" },
  { name: ">", label: "greater than" },
  { name: ">=", label: "greater than or equal" },
  { name: "contains", label: "contains" },
  { name: "beginsWith", label: "starts with" },
  { name: "endsWith", label: "ends with" },
  { name: "in", label: "is one of" },
  { name: "notIn", label: "is not one of" },
] as const

const MAX_SAVED_QUERIES = 100
const MAX_NAME_LENGTH = 120
const COMPLEX_FIELD_TYPES = new Set([
  "location",
  "region",
  "regions",
  "relation",
  "image",
  "images",
  "marker",
])
const NUMERIC_FIELD_TYPES = new Set(["number", "post"])
const OPTION_FIELD_TYPES = new Set(["select", "radio", "status"])

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function isSourceRole(value: unknown): value is DataSourceRole {
  return value === "objects" || value === "regions"
}

function isBuilder(value: unknown): value is RuleGroupType {
  return (
    isPlainObject(value) &&
    (value.combinator === "and" || value.combinator === "or") &&
    Array.isArray(value.rules)
  )
}

function isPrismaDataQuery(value: unknown): value is PrismaDataQuery {
  if (!isPlainObject(value)) return false
  const allowed = new Set(["where", "select", "orderBy", "take", "skip"])
  if (Object.keys(value).some((key) => !allowed.has(key))) return false
  if (value.where != null && !isPlainObject(value.where)) return false
  if (value.select != null && !Array.isArray(value.select)) return false
  if (value.take != null && (!Number.isInteger(value.take) || Number(value.take) < 0)) return false
  if (value.skip != null && (!Number.isInteger(value.skip) || Number(value.skip) < 0)) return false
  return true
}

function cloneBuilder(builder: RuleGroupType): RuleGroupType {
  return JSON.parse(JSON.stringify(builder)) as RuleGroupType
}

function cloneQuery(query: PrismaDataQuery): PrismaDataQuery {
  return JSON.parse(JSON.stringify(query)) as PrismaDataQuery
}

function fieldIsNumeric(field: SchemaField): boolean {
  const type = String(field.type ?? "").toLowerCase()
  const dbType = String(field.db_type ?? "")
  if (NUMERIC_FIELD_TYPES.has(type)) return true
  if (type === "id") {
    return /^(?:tinyint|smallint|mediumint|int|bigint|float|double|decimal|numeric)/i.test(dbType)
  }
  return /^(?:tinyint|smallint|mediumint|int|bigint|float|double|decimal|numeric)/i.test(dbType)
}

/**
 * Only fields supported by the Plasma simple-query path are exposed.
 * Virtual/compound fields are intentionally omitted until #130 owns them.
 */
export function queryBuilderFieldsForSchema(schema: DataSchema): Field[] {
  const result: Field[] = []
  const seen = new Set<string>()

  for (const field of schema.fields ?? []) {
    const name = typeof field.name === "string" ? field.name.trim() : ""
    const type = String(field.type ?? "").toLowerCase()
    if (!name || seen.has(name) || COMPLEX_FIELD_TYPES.has(type)) continue
    seen.add(name)

    const numeric = fieldIsNumeric(field)
    const boolean = type === "checkbox" || type === "boolean"
    const optionField = OPTION_FIELD_TYPES.has(type) && Array.isArray(field.options)
    const operators = boolean
      ? PLASMA_QUERY_OPERATORS.slice(0, 2)
      : optionField
        ? PLASMA_QUERY_OPERATORS.filter((operator) =>
            ["=", "!=", "in", "notIn"].includes(operator.name),
          )
        : numeric
          ? PLASMA_QUERY_OPERATORS.filter((operator) =>
              ["=", "!=", "<", "<=", ">", ">=", "in", "notIn"].includes(operator.name),
            )
          : PLASMA_QUERY_OPERATORS

    const queryField: Field = {
      name,
      label: field.label?.trim() || name,
      operators: operators.map((operator) => ({ ...operator })),
      inputType: boolean ? "checkbox" : numeric ? "number" : "text",
    }

    if (optionField && field.options && field.options.length > 0) {
      queryField.valueEditorType = "select"
      queryField.values = field.options
        .filter((option) => option.value !== undefined && option.value !== null)
        .map((option) => ({
          name: String(option.value),
          label: option.label?.trim() || String(option.value),
        }))
    }

    result.push(queryField)
  }

  return result
}

export function readSavedDataQueries(database: unknown): SavedDataQuery[] {
  if (!isPlainObject(database) || !Array.isArray(database.queries)) return []

  const seen = new Set<string>()
  const result: SavedDataQuery[] = []
  for (const raw of database.queries.slice(0, MAX_SAVED_QUERIES)) {
    if (!isPlainObject(raw)) continue
    const id = typeof raw.id === "string" ? raw.id.trim() : ""
    const name = typeof raw.name === "string" ? raw.name.trim() : ""
    const schemaId = typeof raw.schemaId === "string" ? raw.schemaId.trim() : ""
    if (
      !id ||
      seen.has(id) ||
      !name ||
      name.length > MAX_NAME_LENGTH ||
      !schemaId ||
      !isSourceRole(raw.sourceRole) ||
      !isBuilder(raw.builder) ||
      !isPrismaDataQuery(raw.query)
    ) {
      continue
    }

    seen.add(id)
    result.push({
      id,
      name,
      schemaId,
      sourceRole: raw.sourceRole,
      builder: cloneBuilder(raw.builder),
      query: cloneQuery(raw.query),
    })
  }
  return result
}

export function readMapSavedDataQueries(map: MapsvgMapInstance | null): SavedDataQuery[] {
  return readSavedDataQueries(readLiveDatabase(map))
}

export function prismaQueryFromBuilder(builder: RuleGroupType): PrismaDataQuery {
  const where = formatQuery(builder, {
    format: "prisma",
    parseNumbers: "strict",
  })
  if (!isPlainObject(where)) {
    throw new Error("React Query Builder produced an invalid Prisma filter.")
  }
  return { where }
}

export function createSavedDataQuery(
  input: Omit<SavedDataQuery, "id" | "query"> & { id?: string },
): SavedDataQuery {
  const name = input.name.trim()
  if (!name || name.length > MAX_NAME_LENGTH) {
    throw new Error(`Query name must be 1–${MAX_NAME_LENGTH} characters.`)
  }
  if (!input.schemaId.trim()) throw new Error("A data source is required.")

  const id = input.id?.trim() || createQueryId()
  return {
    id,
    name,
    schemaId: input.schemaId.trim(),
    sourceRole: input.sourceRole,
    builder: cloneBuilder(input.builder),
    query: prismaQueryFromBuilder(input.builder),
  }
}

export function upsertSavedDataQuery(
  queries: SavedDataQuery[],
  next: SavedDataQuery,
): SavedDataQuery[] {
  const index = queries.findIndex((query) => query.id === next.id)
  if (index < 0) return [...queries, next]
  return queries.map((query, current) => (current === index ? next : query))
}

export function deleteSavedDataQuery(queries: SavedDataQuery[], id: string): SavedDataQuery[] {
  return queries.filter((query) => query.id !== id)
}

export function writeMapSavedDataQueries(
  map: MapsvgMapInstance | null,
  queries: SavedDataQuery[],
): void {
  if (!map) throw new Error("A loaded map is required to save data queries.")
  const database = readLiveDatabase(map)
  patchLiveMapOptions({
    database: {
      ...database,
      queries: queries.slice(0, MAX_SAVED_QUERIES).map((query) => ({
        ...query,
        builder: cloneBuilder(query.builder),
        query: cloneQuery(query.query),
      })),
    },
  })
}

function createQueryId(): string {
  const uuid = globalThis.crypto?.randomUUID?.()
  if (uuid) return uuid
  return `query-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`
}
