import { useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react"
import { Loader2, MapPin, Trash2, Upload } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { MarkerImagePicker } from "@/components/settings/marker-data-rules/MarkerImagePicker"
import { LocationPickerMap } from "./LocationPickerMap"
import { useControlRequest } from "../schema-form/useControlRequest"
import type { SchemaFieldControlProps } from "../schema-form/types"
import { locationAdapterFromContext, type LocationSearchResult, type LocationValue } from "./types"
import {
  locationAddressLabel,
  locationFromCoordinateQuery,
  locationFromSearchResult,
  locationValue,
  markerOptionPath,
  markerPath,
  withMarkerPath,
} from "./value"

export function LocationFieldControl(props: SchemaFieldControlProps) {
  const { field, value, disabled, context, onChange } = props
  const adapter = locationAdapterFromContext(context)
  const [pickerGeo, setPickerGeo] = useState<{ mapId: number; geo: boolean } | null>(null)
  const isGeo = adapter?.picker && pickerGeo?.mapId === adapter.picker.mapId ? pickerGeo.geo : adapter?.isGeo
  const { owner, begin, cancel } = useControlRequest(props, adapter)
  const timer = useRef<number | null>(null)
  const markerUploadInput = useRef<HTMLInputElement>(null)
  const current = locationValue(value)
  const [query, setQuery] = useState("")
  const [results, setResults] = useState<LocationSearchResult[]>([])
  const [selectedResult, setSelectedResult] = useState(0)
  const resultsId = useId()
  const resultsList = useRef<HTMLDivElement>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")
  const [, setMarkerImagesVersion] = useState(0)

  const markerImages = adapter?.markerImages() ?? []
  const markerImagePaths = markerImages.map(markerOptionPath).filter(Boolean)
  const defaultMarkerPath = adapter?.markerDefaults?.image || (typeof field.defaultMarkerPath === "string" ? field.defaultMarkerPath : "") || markerImagePaths.find(path => path.endsWith("/_pin_default.png")) || ""
  const currentMarkerPath = markerPath(current, defaultMarkerPath)
  const appliedMarkerPath = currentMarkerPath
  const presentedCurrent = current && appliedMarkerPath ? withMarkerPath(current, appliedMarkerPath) : current
  const inheritMarker = (next: LocationValue | null) => next && !current && defaultMarkerPath ? withMarkerPath(next, defaultMarkerPath) : next
  const latestRememberImage = useRef(adapter?.markerDefaults?.rememberImage)

  const bindingOwner = useMemo(
    () => ({}),
    [adapter, props.recordOwner, disabled, field.name, field.type],
  )
  const currentBinding = useRef<object | null>(null)
  const bindingCallback = useRef(onChange)
  useLayoutEffect(() => {
    bindingCallback.current = next => onChange(inheritMarker(next))
    latestRememberImage.current = adapter?.markerDefaults?.rememberImage
  })

  useLayoutEffect(() => {
    setQuery("")
    setResults([])
    setSelectedResult(0)
    setBusy(false)
    setError("")
  }, [owner])

  useEffect(() => {
    resultsList.current?.querySelector<HTMLElement>('[aria-selected="true"]')?.scrollIntoView?.({ block: "nearest" })
  }, [results, selectedResult])

  useLayoutEffect(() => {
    currentBinding.current = bindingOwner
    const unbind = adapter?.bind((next) => {
      if (currentBinding.current === bindingOwner && !disabled) bindingCallback.current(next)
    })
    adapter?.sync(presentedCurrent)
    return () => {
      if (currentBinding.current === bindingOwner) currentBinding.current = null
      unbind?.()
    }
    // Local value edits already sync through apply()/the Map itself. Rebinding
    // on those edits would remove and recreate the existing editing marker.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [bindingOwner])

  const cancelSearch = () => {
    if (timer.current !== null) window.clearTimeout(timer.current)
    timer.current = null
    cancel()
  }

  useEffect(() => {
    const searchText = query.trim()
    if (
      !adapter || !isGeo ||
      disabled ||
      searchText.length < 3 ||
      locationFromCoordinateQuery(searchText, currentMarkerPath || defaultMarkerPath)
    ) {
      setResults([])
      return
    }
    const ownsRequest = begin()
    timer.current = window.setTimeout(() => {
      timer.current = null
      setBusy(true)
      setError("")
      void adapter
        .search(searchText, typeof field.language === "string" ? field.language : undefined)
        .then((nextResults) => {
          if (ownsRequest()) { setResults(nextResults); setSelectedResult(0) }
        })
        .catch((err) => {
          if (ownsRequest()) {
            setResults([])
            setError(err instanceof Error ? err.message : "Location search failed.")
          }
        })
        .finally(() => {
          if (ownsRequest()) setBusy(false)
        })
    }, 500)
    return cancelSearch
    // begin is stable for a committed record; cleanup also retires manual work
    // if the query, language or record changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [owner, adapter, isGeo, currentMarkerPath, defaultMarkerPath, disabled, field.language, query])

  const apply = (next: LocationValue | null) => {
    const located = inheritMarker(next)
    adapter?.sync(located)
    onChange(located)
  }

  const search = async () => {
    if (!adapter || !query.trim() || disabled || busy) return
    cancelSearch()
    const ownsRequest = begin()

    const coordinates = locationFromCoordinateQuery(query, currentMarkerPath || defaultMarkerPath)
    if (coordinates) {
      apply(coordinates)
      setQuery("")
      setResults([])
      return
    }

    if (!isGeo) {
      setError("Address search is available only for geo maps.")
      return
    }

    setBusy(true)
    setError("")
    try {
      const found = await adapter.search(
        query.trim(),
        typeof field.language === "string" ? field.language : undefined,
      )
      if (ownsRequest()) { setResults(found); setSelectedResult(0) }
    } catch (err) {
      if (ownsRequest()) setError(err instanceof Error ? err.message : "Location search failed.")
    } finally {
      if (ownsRequest()) setBusy(false)
    }
  }
  const chooseResult = (result: LocationSearchResult) => {
    if (disabled || !adapter) return
    const next = locationFromSearchResult(result, currentMarkerPath || defaultMarkerPath)
    if (next) {
      cancelSearch()
      setBusy(false)
      apply(next)
      setQuery("")
      setResults([])
      setSelectedResult(0)
    }
  }

  const chooseMarker = (path: string) => {
    if (disabled || !current) return
    const next = withMarkerPath(current, path)
    if (next) {
      apply(next)
      const remember = adapter?.markerDefaults?.rememberImage
      void remember?.(path).catch(err => {
        if (currentBinding.current && latestRememberImage.current === remember) setError(err instanceof Error ? err.message : "Could not remember marker image.")
      })
    }
  }

  const uploadMarker = async (file?: File) => {
    if (!file || !adapter?.uploadMarker || disabled || busy) return
    cancelSearch()
    const ownsRequest = begin()
    setBusy(true)
    setError("")
    try {
      const marker = await adapter.uploadMarker(file)
      if (!ownsRequest()) return
      setMarkerImagesVersion((version) => version + 1)
      const path = markerOptionPath(marker)
      if (path) chooseMarker(path)
    } catch (err) {
      if (ownsRequest()) setError(err instanceof Error ? err.message : "Marker upload failed.")
    } finally {
      if (ownsRequest()) setBusy(false)
    }
  }

  return (
    <div className="grid gap-3">
      <div className="flex items-center gap-2 rounded-md border p-3">
        {current && appliedMarkerPath ? <span className="flex size-9 shrink-0 items-center justify-center"><img src={appliedMarkerPath} alt="Marker image" className="max-h-8 max-w-8 object-contain" /></span> : <MapPin className="size-4 shrink-0 text-muted-foreground" />}
        <div className="min-w-0 flex-1">
          <div className="truncate text-sm">
            {locationAddressLabel(current) || "No location selected"}
          </div>
          {current && adapter ? <MarkerImagePicker
            label="Change marker"
            trigger="link"
            value={appliedMarkerPath}
            images={markerImagePaths}
            onChange={chooseMarker}
            disabled={disabled}
            resetKey={bindingOwner}
            footer={adapter.uploadMarker ? <Button type="button" variant="ghost" size="sm" className="w-full justify-start" aria-label="Upload marker" disabled={disabled || busy} onClick={() => markerUploadInput.current?.click()}><Upload />Upload</Button> : null}
          /> : null}
        </div>
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label="Clear location"
          disabled={disabled || !current}
          onClick={() => apply(null)}
        >
          <Trash2 />
        </Button>
      </div>
      {adapter?.uploadMarker ? <input ref={markerUploadInput} aria-label="Upload marker file" type="file" accept="image/*" hidden disabled={disabled || busy} onChange={event => { void uploadMarker(event.target.files?.[0]); event.currentTarget.value = "" }} /> : null}

      <div className="relative min-w-0">
        <Input
          value={query}
          disabled={disabled || !adapter}
          role="combobox"
          aria-label="Search address or coordinates"
          aria-autocomplete="list"
          aria-expanded={results.length > 0}
          aria-controls={results.length ? resultsId : undefined}
          aria-activedescendant={results[selectedResult] ? `${resultsId}-${selectedResult}` : undefined}
          aria-busy={busy}
          autoComplete="off"
          className="pr-7"
          placeholder={
            isGeo ? "Search address or enter lat,lng" : "Enter lat,lng or click the map"
          }
          onChange={(event) => {
            cancelSearch()
            setBusy(false)
            setResults([])
            setSelectedResult(0)
            setQuery(event.target.value)
          }}
          onKeyDown={(event) => {
            if (disabled || event.nativeEvent.isComposing) return
            if (results.length && (event.key === "ArrowDown" || event.key === "ArrowUp")) {
              event.preventDefault()
              setSelectedResult(index => (index + (event.key === "ArrowDown" ? 1 : -1) + results.length) % results.length)
              return
            }
            if (event.key === "Enter") {
              event.preventDefault()
              if (results.length) chooseResult(results[selectedResult] ?? results[0])
              else void search()
            }
            if (event.key === "Escape") {
              event.preventDefault()
              cancelSearch()
              setBusy(false)
              setResults([])
              setSelectedResult(0)
            }
          }}
        />
        {busy ? <Loader2 aria-hidden="true" className="pointer-events-none absolute right-2 top-1/2 size-3.5 -translate-y-1/2 animate-spin text-muted-foreground" /> : null}
        {results.length ? (
          <div ref={resultsList} id={resultsId} role="listbox" aria-label="Address suggestions" className="absolute left-0 right-0 top-full z-50 mt-1 max-h-64 overflow-auto rounded-md border bg-popover p-1 text-popover-foreground shadow-md">
            {results.map((result, index) => (
              <button
                type="button"
                id={`${resultsId}-${index}`}
                role="option"
                aria-selected={selectedResult === index}
                tabIndex={-1}
                key={`${result.formatted_address}-${index}`}
                className="block w-full rounded-sm px-2 py-2 text-left text-sm hover:bg-accent hover:text-accent-foreground aria-selected:bg-accent aria-selected:text-accent-foreground"
                onMouseDown={(event) => event.preventDefault()}
                onMouseEnter={() => setSelectedResult(index)}
                disabled={disabled}
                onClick={() => chooseResult(result)}
              >
                {result.formatted_address}
              </button>
            ))}
          </div>
        ) : null}
      </div>

      {adapter?.picker ? <LocationPickerMap picker={adapter.picker} value={presentedCurrent} recordOwner={props.recordOwner} disabled={disabled} onChange={apply} onGeoChange={geo => setPickerGeo({ mapId: adapter.picker!.mapId, geo })} /> : null}

      {!adapter ? (
        <div className="text-xs text-muted-foreground">
          Location adapter is not connected. Existing location data is preserved.
        </div>
      ) : adapter.hasMapInteraction ? (
        <div className="text-xs text-muted-foreground">
          You can also click the map to create or move the editing marker.
        </div>
      ) : (
        <div className="text-xs text-muted-foreground">
          Search by address or enter coordinates as lat,lng.
        </div>
      )}
      {error ? <div className="text-xs text-destructive">{error}</div> : null}
    </div>
  )
}
