import { useEffect, useRef, useState } from "react"
import { ChevronDown } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Command, CommandEmpty, CommandInput, CommandItem, CommandList } from "@/components/ui/command"
import { fetchLocationPickerMap, fetchLocationPickerMaps } from "@/lib/mapsvg-api"
import { loadPreviewFrame } from "@/lib/preview-frame"
import { createMapSvgLocationAdapter } from "./adapter"
import { locationPickerOptions } from "./picker-options"
import type { LocationFieldAdapter, LocationValue } from "./types"

type Props = { picker: NonNullable<LocationFieldAdapter["picker"]>; value: LocationValue | null; disabled: boolean; recordOwner?: object; onGeoChange?: (isGeo: boolean) => void; onChange: (value: LocationValue | null) => void }
type PickerRuntime = { map: any; adapter: LocationFieldAdapter; focusedPoint?: string; focusedOwner?: object; cancelFocus?: () => void }

/** Geographic locations stay portable across maps and longitudinal world copies. */
export function pickerLocation(value: LocationValue | null): LocationValue | null {
  if (!value?.geoPoint) return value
  const { svgPoint: _svgPoint, ...geo } = value
  const { lat, lng } = value.geoPoint
  return { ...geo, geoPoint: { lat, lng: lng >= -180 && lng <= 180 ? lng : ((lng + 180) % 360 + 360) % 360 - 180 } }
}

export function LocationPickerMap({ picker, value, disabled, recordOwner, onChange, onGeoChange }: Props) {
  const frame = useRef<HTMLIFrameElement>(null)
  const live = useRef<PickerRuntime | null>(null)
  const applying = useRef(false)
  const current = useRef({ value, disabled, recordOwner, onChange, onGeoChange })
  current.current = { value, disabled, recordOwner, onChange, onGeoChange }
  const [status, setStatus] = useState("Loading map…")
  const [error, setError] = useState("")
  const [retry, setRetry] = useState(0)
  const [aspectRatio, setAspectRatio] = useState(1.5)
  const [open, setOpen] = useState(false)
  const [maps, setMaps] = useState<Array<{ id: number; title: string }>>([])
  const [menuError, setMenuError] = useState("")
  const pointKey = JSON.stringify([value?.geoPoint, value?.svgPoint])

  const sync = (focus: boolean, instant = false) => {
    const runtime = live.current
    if (!runtime) return
    const next = pickerLocation(current.current.value)
    if (!next) {
      runtime.cancelFocus?.()
      runtime.cancelFocus = undefined
      runtime.focusedPoint = undefined
    }
    if ((next?.geoPoint && !runtime.map.isGeo()) || (next?.svgPoint && !next.geoPoint && runtime.map.isGeo())) {
      runtime.cancelFocus?.()
      runtime.cancelFocus = undefined
      runtime.focusedPoint = undefined
      applying.current = true
      try { runtime.adapter.sync(null) } finally { applying.current = false }
      setError("This location uses different coordinates. Choose a compatible map or click to set a new location.")
      return
    }
    setError("")
    applying.current = true
    try {
      // Runtime click locations also contain source-specific SVG coordinates.
      // Those must not override the geographic point after changing the camera/map.
      const previous = runtime.map.getEditingMarker?.()
      if (next?.geoPoint && previous?.location) delete previous.location.svgPoint
      runtime.adapter.sync(next)
      const marker = runtime.map.getEditingMarker?.()
      if (next?.geoPoint && marker && runtime.map.converter) marker.setSvgPoint(runtime.map.converter.convertGeoToSVG(next.geoPoint))
    } finally { applying.current = false }
    const focusKey = JSON.stringify([next?.geoPoint, next?.svgPoint])
    if (focus && next && (runtime.focusedPoint !== focusKey || runtime.focusedOwner !== current.current.recordOwner)) {
      runtime.cancelFocus?.()
      runtime.cancelFocus = undefined
      runtime.focusedPoint = focusKey
      runtime.focusedOwner = current.current.recordOwner
      if (next.geoPoint && runtime.map.googleMaps?.map) {
        const googleMap = runtime.map.googleMaps.map
        if (instant) {
          googleMap.setCenter(next.geoPoint)
          if (googleMap.getZoom() !== 15) googleMap.setZoom(15)
        } else {
          if (googleMap.getZoom() !== 15) {
            if (googleMap.getCenter()?.equals(next.geoPoint)) {
              googleMap.setZoom(15)
            } else {
              // Changing zoom during panTo interrupts its native animation.
              // Finish the pan before applying the required marker zoom.
              let active = true
              const listener = googleMap.addListener("idle", () => {
                if (!active || live.current !== runtime) return
                active = false
                listener.remove()
                runtime.cancelFocus = undefined
                if (googleMap.getZoom() !== 15) googleMap.setZoom(15)
              })
              runtime.cancelFocus = () => { active = false; listener.remove() }
            }
          }
          googleMap.panTo(next.geoPoint)
        }
      } else {
        const marker = runtime.map.getEditingMarker?.()
        if (marker) next.geoPoint ? runtime.map.zoomTo([marker], 15) : runtime.map.centerOn(marker)
      }
    }
  }

  useEffect(() => {
    const iframe = frame.current
    if (!iframe) return
    const lifetime = new AbortController()
    let map: any
    let unbind: (() => void) | undefined
    let timeout: ReturnType<typeof setTimeout> | undefined
    setStatus("Loading map…")
    setError("")
    void Promise.all([loadPreviewFrame(iframe, lifetime.signal), fetchLocationPickerMap(picker.mapId, lifetime.signal)]).then(([client, surface]) => {
      if (lifetime.signal.aborted) return
      const doc = iframe.contentDocument!
      doc.body.style.cssText = "margin:0;padding:0;height:100vh;min-height:0;display:block;overflow:hidden"
      const container = doc.createElement("div")
      container.style.cssText = "width:100%;height:100%"
      doc.body.append(container)
      const failed = (reason: unknown) => {
        if (!lifetime.signal.aborted) { setStatus(""); setError(reason instanceof Error ? reason.message : "Could not load map.") }
      }
      map = new client.map(container, { id: 0, version: "9.0.0", svgFileLastChanged: surface.svgFileLastChanged, options: locationPickerOptions(surface.options) }, { prefetch: false, inBackend: false, onLoadError: failed })
      timeout = setTimeout(() => failed(new Error("Map took too long to load. Try again.")), 35000)
      map.events.once("afterInit", () => {
        if (lifetime.signal.aborted) return
        clearTimeout(timeout)
        const adapter = createMapSvgLocationAdapter(map, { runtimeClient: iframe.contentWindow?.mapsvg })
        live.current = { map, adapter }
        current.current.onGeoChange?.(Boolean(map.isGeo()))
        const box = map.getMapContainerSize?.() ?? map.svgDefault?.viewBox ?? map.getViewBox?.()
        if (box?.width > 0 && box?.height > 0) setAspectRatio(box.width / box.height)
        unbind = adapter.bind(raw => {
          if (lifetime.signal.aborted || current.current.disabled || applying.current) return
          const next = pickerLocation(raw)
          current.current = { ...current.current, value: next }
          sync(true)
          current.current.onChange(next)
        })
        map.setMarkersEditMode(!current.current.disabled, true)
        sync(true, true)
        setStatus("")
      })
    }).catch(reason => {
      if (!lifetime.signal.aborted) { setStatus(""); setError(reason instanceof Error ? reason.message : "Could not load map.") }
    })
    return () => {
      lifetime.abort()
      clearTimeout(timeout)
      live.current?.cancelFocus?.()
      live.current = null
      unbind?.()
      try { map?.destroy() } catch { /* Retired frame owns any remaining DOM. */ }
    }
  }, [picker.mapId, retry])
  useEffect(() => { sync(true) }, [pointKey, recordOwner])
  useEffect(() => { sync(false) }, [JSON.stringify(value)])
  useEffect(() => {
    live.current?.map.setMarkersEditMode(!disabled, true)
    if (disabled) { live.current?.cancelFocus?.(); if (live.current) live.current.cancelFocus = undefined }
  }, [disabled])
  useEffect(() => {
    if (!open) return
    const abort = new AbortController()
    setMenuError("")
    void fetchLocationPickerMaps(abort.signal).then(items => { if (!abort.signal.aborted) setMaps(items) }).catch(reason => {
      if (!abort.signal.aborted) setMenuError(reason instanceof Error ? reason.message : "Could not load maps.")
    })
    return () => abort.abort()
  }, [open])

  return <div className="grid gap-1.5">
    <div className="relative overflow-hidden rounded-md border">
      <iframe ref={frame} title="Location map" className="block w-full border-0" style={{ aspectRatio }} />
      {status ? <div role="status" className="absolute inset-0 grid place-items-center bg-background text-xs text-muted-foreground">{status}</div> : null}
    </div>
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild><Button type="button" variant="ghost" size="sm" className="w-fit" disabled={disabled}>Change map<ChevronDown className="size-3" /></Button></PopoverTrigger>
      <PopoverContent align="start" className="w-72 p-0"><Command>
        <CommandInput placeholder="Search maps…" /><CommandList><CommandEmpty>No maps found.</CommandEmpty>
          {[{ id: 0, title: "Google Map" }, ...maps].map(item => <CommandItem key={item.id} value={`${item.title} ${item.id}`} onSelect={() => {
            setOpen(false)
            void picker.rememberMap(item.id).catch(reason => setError(reason instanceof Error ? reason.message : "Could not remember map."))
          }}>{item.title}</CommandItem>)}
        </CommandList>
      </Command></PopoverContent>
    </Popover>
    {menuError || error || picker.error ? <div role="alert" className="text-xs text-destructive">{menuError || error || picker.error}<Button type="button" variant="link" size="sm" onClick={() => setRetry(n => n + 1)}>Retry</Button></div> : null}
  </div>
}
