import {
  getFormFieldDefaults,
  type FormFieldData,
} from "../../../../../mapsvg/FormBuilder/FieldDefinitions"

export const SIMPLE_SCHEMA_FIELD_TYPES = [
  "text",
  "textarea",
  "checkbox",
  "checkboxes",
  "radio",
  "select",
  "date",
  "status",
  "title",
  "colorpicker",
] as const

export type SimpleSchemaFieldType = (typeof SIMPLE_SCHEMA_FIELD_TYPES)[number]

export const COMPLEX_SCHEMA_FIELD_TYPES = ["image", "post", "region", "location"] as const

export const FILTER_SCHEMA_FIELD_TYPES = ["search", "distance"] as const

export const DEFAULT_SCHEMA_FIELD_TYPES = [
  ...SIMPLE_SCHEMA_FIELD_TYPES,
  ...COMPLEX_SCHEMA_FIELD_TYPES,
] as const

export type SchemaBuilderFieldType = string

export type SchemaBuilderValidationError = {
  index?: number
  message: string
}

const RESERVED_FIELDS = new Set([
  "lat",
  "lon",
  "lng",
  "location",
  "location_lat",
  "location_lon",
  "location_lng",
  "location_address",
  "location_img",
  "marker",
  "marker_id",
  "regions",
  "region_id",
  "post",
  "post_title",
  "post_url",
  "keywords",
  "status",
])

const RESERVED_FIELD_TYPES: Record<string, string> = {
  regions: "region",
  status: "status",
  post: "post",
  marker: "marker",
  location: "location",
}
function cloneOption(option: any): any {
  if (!option || typeof option !== "object") {
    return option
  }

  const cloned = { ...option }
  if (Array.isArray(cloned.options)) {
    cloned.options = cloned.options.map(cloneOption)
  }
  return cloned
}

export function cloneSchemaFields(fields: FormFieldData[]): FormFieldData[] {
  return fields.map((field) => ({
    ...field,
    ...(Array.isArray(field.options) ? { options: field.options.map(cloneOption) } : {}),
    ...(field.optionsDict && typeof field.optionsDict === "object"
      ? { optionsDict: { ...field.optionsDict } }
      : {}),
  }))
}

export function sanitizeFieldName(value: string): string {
  const cleaned = value.replace(/[^a-zA-Z0-9_]/g, "")
  if (!cleaned) {
    return ""
  }
  return cleaned[0].replace(/[^a-zA-Z_]/g, "") + cleaned.slice(1)
}

function humanizeType(type: string): string {
  if (type === "colorpicker") return "Color"
  if (type === "checkboxes") return "Checkboxes"
  return type.charAt(0).toUpperCase() + type.slice(1)
}

function uniqueName(baseName: string, fields: FormFieldData[]): string {
  const names = new Set(fields.map((field) => String(field.name ?? "")))
  if (!names.has(baseName)) {
    return baseName
  }
  let index = 2
  while (names.has(`${baseName}_${index}`)) {
    index += 1
  }
  return `${baseName}_${index}`
}
export function createSchemaField(
  type: SchemaBuilderFieldType,
  fields: FormFieldData[],
): FormFieldData {
  const defaults = getFormFieldDefaults(type)
  const defaultName = typeof defaults.name === "string" && defaults.name ? defaults.name : type
  const fixedName = ["status", "post", "region", "relation"].includes(type)
  const name = fixedName ? defaultName : uniqueName(defaultName, fields)

  return {
    ...defaults,
    type,
    label:
      typeof defaults.label === "string" && defaults.label ? defaults.label : humanizeType(type),
    name,
  }
}

export function updateSchemaField(
  fields: FormFieldData[],
  index: number,
  patch: Record<string, any>,
): FormFieldData[] {
  return fields.map((field, fieldIndex) => (fieldIndex === index ? { ...field, ...patch } : field))
}

export function removeSchemaField(fields: FormFieldData[], index: number): FormFieldData[] {
  if (fields[index]?.protected === true) {
    return fields
  }
  return fields.filter((_, fieldIndex) => fieldIndex !== index)
}

export function moveSchemaField(
  fields: FormFieldData[],
  from: number,
  to: number,
): FormFieldData[] {
  if (from === to || from < 0 || to < 0 || from >= fields.length || to >= fields.length) {
    return fields
  }

  const next = [...fields]
  const [field] = next.splice(from, 1)
  next.splice(to, 0, field)
  return next
}
export function buildFieldOptionsPatch(
  field: FormFieldData,
  options: Array<{ label: string; value: string }>,
): Record<string, any> {
  if (field.type === "select") {
    return {
      options,
      optionsDict: Object.fromEntries(options.map((option) => [option.value, option.label])),
    }
  }

  if (field.type === "status") {
    return {
      options,
      optionsDict: Object.fromEntries(options.map((option) => [option.value, option])),
    }
  }

  return { options }
}

export function serializeFieldOptions(field: FormFieldData): string {
  if (!Array.isArray(field.options)) {
    return ""
  }

  return field.options
    .filter((option) => option && typeof option === "object")
    .map((option) => `${option.label ?? ""}:${option.value ?? ""}`)
    .join("\n")
}

export function parseFieldOptions(value: string): Array<{
  label: string
  value: string
}> {
  return value
    .split("\n")
    .map((row) => row.trim())
    .filter(Boolean)
    .flatMap((row) => {
      const separator = row.indexOf(":")
      if (separator < 0) {
        return []
      }
      return [
        {
          label: row.slice(0, separator).trim(),
          value: row.slice(separator + 1).trim(),
        },
      ]
    })
}

function isRelationType(type: string): boolean {
  return type === "region" || type === "relation"
}

export function validateSchemaFields(fields: FormFieldData[]): SchemaBuilderValidationError[] {
  const errors: SchemaBuilderValidationError[] = []
  const counts = new Map<string, number>()

  fields.forEach((field) => {
    const name = String(field.name ?? "")
    counts.set(name, (counts.get(name) ?? 0) + 1)
  })

  fields.forEach((field, index) => {
    const name = String(field.name ?? "")
    if (!name) {
      errors.push({ index, message: "Field name can't be empty" })
    } else if ((counts.get(name) ?? 0) > 1) {
      errors.push({ index, message: "Field names should be unique" })
    } else if (RESERVED_FIELDS.has(name)) {
      const reservedType = RESERVED_FIELD_TYPES[name]
      const typeOk =
        reservedType === "region" ? isRelationType(field.type) : reservedType === field.type
      if (!reservedType || !typeOk) {
        errors.push({
          index,
          message: `Field name "${name}" is reserved, please set another name`,
        })
      }
    }
    if (Array.isArray(field.options) && !isRelationType(field.type) && field.type !== "marker") {
      const values = field.options
        .filter((option) => option && typeof option === "object")
        .map((option) => String(option.value ?? ""))
      if (new Set(values).size !== values.length) {
        errors.push({
          index,
          message: 'Check "Options" list - values should not repeat',
        })
      }
    }
  })

  return errors
}

export function canAddSchemaField(type: SchemaBuilderFieldType, fields: FormFieldData[]): boolean {
  const singletonTypes = new Set([
    "status",
    "post",
    "region",
    "relation",
    "location",
    "distance",
    "search",
  ])

  if (!singletonTypes.has(type)) {
    return true
  }

  if (type === "region" || type === "relation") {
    return !fields.some((field) => field.type === "region" || field.type === "relation")
  }

  return !fields.some((field) => field.type === type)
}

export function isFieldNameLocked(field: FormFieldData): boolean {
  return (
    field.renamable === false ||
    field.type === "status" ||
    field.type === "title" ||
    field.type === "id" ||
    field.type === "post" ||
    field.type === "region" ||
    field.type === "relation" ||
    field.type === "location" ||
    field.type === "search" ||
    field.type === "distance"
  )
}
