import { CommonSettings, SearchableSettings, TextSetting } from "../schema-builder/settings"
import type { SchemaFieldSettingsProps } from "../schema-builder/types"

/** Marker presentation belongs to Marker settings; retained schema properties survive saves. */
export function LocationFieldSettings(props: SchemaFieldSettingsProps) {
  return (
    <CommonSettings {...props}>
      <TextSetting label="Language" value={props.field.language}
        description="Geocoding language. Leave blank to inherit map settings."
        onChange={(language) => props.onPatch({ language })} />
      <SearchableSettings field={props.field} onPatch={props.onPatch} />
    </CommonSettings>
  )
}
