import { useMemo } from "react"
import { type ColumnDef } from "@tanstack/react-table"
import { Trash2Icon } from "lucide-react"
import { DataTable, type DataTablePaginationState, type DataTableServerState, type DataTableVariant } from "@/components/ui/data-table"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { formatCellValue, listColumns, type DataSchema, type SchemaField } from "@/lib/mapsvg-api"
import { cn } from "@/lib/utils"

type DataRow = Record<string, unknown>

type Props = {
  variant?: DataTableVariant
  serverState?: DataTableServerState
  paginationState?: DataTablePaginationState
  schema: DataSchema | null
  rows: DataRow[]
  loading?: boolean
  className?: string
  /** Trash click — selection-only for now if omitted. */
  onDeleteRow?: (row: DataRow) => void
  readOnly?: boolean
  onRowClick?: (row: DataRow) => void
  selectedRow?: DataRow | null
}

function buildColumns(
  fields: SchemaField[],
  onDeleteRow?: (row: DataRow) => void,
  readOnly = false,
): ColumnDef<DataRow>[] {
  const selectCol: ColumnDef<DataRow> = {
    id: "select",
    enableHiding: false,
    enableSorting: false,
    header: ({ table }) => (
      <Checkbox
        checked={
          table.getIsAllPageRowsSelected() || (table.getIsSomePageRowsSelected() && "indeterminate")
        }
        onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
        aria-label="Select all"
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        checked={row.getIsSelected()}
        onCheckedChange={(value) => row.toggleSelected(!!value)}
        aria-label="Select row"
      />
    ),
  }

  const dataCols: ColumnDef<DataRow>[] = fields.map((field) => ({
    id: field.name,
    accessorFn: (row) => formatCellValue(row, field),
    meta: { label: field.label || field.name },
    header: field.label || field.name,
    cell: ({ row }) => {
      const text = formatCellValue(row.original, field)
      return (
        <span className="block truncate" title={text}>
          {text}
        </span>
      )
    },
  }))

  const actionsCol: ColumnDef<DataRow> = {
    id: "actions",
    enableHiding: false,
    enableSorting: false,
    header: () => <span className="sr-only">Actions</span>,
    cell: ({ row }) => (
      <Button
        type="button"
        variant="ghost"
        size="icon-xs"
        className="size-6 text-muted-foreground hover:text-destructive"
        aria-label="Delete row"
        onClick={(event) => { event.stopPropagation(); onDeleteRow?.(row.original) }}
      >
        <Trash2Icon className="size-4" />
      </Button>
    ),
  }

  return readOnly ? dataCols : [selectCol, ...dataCols, actionsCol]
}

/** Data source List — TanStack DataTable (select, search, columns, trash, pagination). */
export function DataListTable({
  variant,
  schema,
  rows,
  serverState,
  paginationState,
  loading,
  className,
  onDeleteRow,
  readOnly = false,
  onRowClick,
  selectedRow = null,
}: Props) {
  const fields = useMemo(() => (schema ? listColumns(schema) : []), [schema])

  const columns = useMemo(
    () => buildColumns(fields, onDeleteRow, readOnly),
    [fields, onDeleteRow, readOnly],
  )

  if (!schema) {
    return (
      <div className={cn("p-3 text-sm text-muted-foreground", className)}>
        Select a data source.
      </div>
    )
  }

  if (loading && !serverState && !paginationState) {
    return <div className={cn("p-3 text-sm text-muted-foreground", className)}>Loading…</div>
  }

  if (fields.length === 0) {
    return (
      <div className={cn("p-3 text-sm text-muted-foreground", className)}>
        This data source has no visible fields.
      </div>
    )
  }

  return (
    <DataTable
      variant={variant}
      className={cn("h-full", className)}
      serverState={serverState}
      paginationState={paginationState}
      columns={columns}
      data={rows}
      searchPlaceholder="Search…"
      pageSize={10}
      onRowClick={onRowClick}
      isRowActive={selectedRow ? (row) => row === selectedRow : undefined}
      showSelectionSummary={!readOnly}
    />
  )
}
