import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import { FormBuilderChoice } from "../FormBuilderChoice"
import { FormBuilderMultiCombobox } from "../FormBuilderCombobox"
import type { SchemaFieldControlProps } from "../schema-form/types"
import { adaptersFromContext, type MapSvgRegionOption } from "./adapters"
import { mergeRegionSelection, regionRefs, selectedRegionIds } from "./value"

export function RegionFieldControl({
  value,
  disabled,
  context,
  onChange,
  recordOwner,
}: SchemaFieldControlProps) {
  const adapter = adaptersFromContext(context).regions
  const scope = adapter?.preferenceKey ?? ""
  const preferenceOwner = useMemo(() => ({ sequence: 0 }), [scope])
  const activePreference = useRef<object | null>(preferenceOwner)
  const [sourceChoice, setSourceChoice] = useState<{ scope: string; value: string } | null>(null)
  const [preferenceError, setPreferenceError] = useState("")
  useLayoutEffect(() => {
    activePreference.current = preferenceOwner
    setPreferenceError("")
    return () => { if (activePreference.current === preferenceOwner) activePreference.current = null }
  }, [preferenceOwner])
  const preferredSource = sourceChoice?.scope === scope ? sourceChoice.value : adapter?.tableName ?? ""
  const [retry, setRetry] = useState(0)
  const tableName = adapter?.sources
    ? adapter.sources.some((source) => source.tableName === preferredSource)
      ? preferredSource
      : ""
    : (adapter?.tableName ?? "")
  const owner = useMemo(() => ({}), [adapter, tableName, recordOwner, retry])
  const current = useRef<object | null>(null)
  useLayoutEffect(() => {
    current.current = owner
    return () => {
      if (current.current === owner) current.current = null
    }
  }, [owner])
  const [result, setResult] = useState<{
    owner: object | null
    regions: MapSvgRegionOption[]
    loading: boolean
    error: string
  }>({ owner: null, regions: [], loading: false, error: "" })
  const { regions, loading, error } =
    result.owner === owner ? result : { regions: [], loading: Boolean(tableName), error: "" }

  useEffect(() => {
    const ownsRead = () => current.current === owner
    setResult({ owner, regions: [], loading: Boolean(tableName), error: "" })
    if (!adapter || !tableName) return

    adapter
      .listRegions(tableName)
      .then((items) => {
        if (ownsRead()) setResult({ owner, regions: items, loading: false, error: "" })
      })
      .catch((err) => {
        if (ownsRead())
          setResult({
            owner,
            regions: [],
            loading: false,
            error: err instanceof Error ? err.message : "Unable to load regions.",
          })
      })
  }, [adapter, tableName, owner])

  if (!adapter) {
    const refs = regionRefs(value)
    return (
      <div className="grid gap-1 text-sm text-muted-foreground">
        {refs.length ? (
          refs.map((ref) => (
            <div key={`${ref.tableName}:${ref.id}`}>
              {ref.title || ref.id} · {ref.tableName}
            </div>
          ))
        ) : (
          <div>No regions selected.</div>
        )}
        <div className="text-xs">Region source adapter is not connected.</div>
      </div>
    )
  }

  const selected = selectedRegionIds(value, tableName)
  const foreignCount = regionRefs(value).filter((region) => region.tableName !== tableName).length

  return (
    <div className="grid gap-2">
      {adapter.sources ? (
        <label className="grid gap-1 text-sm">
          Region collection
          <FormBuilderChoice
            aria-label="Region collection"
            disabled={disabled}
            value={tableName}
            onValueChange={(name) => {
              setSourceChoice({ scope, value: name })
              setPreferenceError("")
              const sequence = ++preferenceOwner.sequence
              void adapter.rememberSource?.(name).catch(error => {
                if (activePreference.current === preferenceOwner && preferenceOwner.sequence === sequence) setPreferenceError(error instanceof Error ? error.message : "Could not remember Region Collection.")
              })
            }}
            emptyLabel="Choose region collection…"
            options={adapter.sources.map((source) => ({
              value: source.tableName,
              label: source.title,
            }))}
          />
          {preferenceError || adapter.preferenceError ? <span className="text-xs text-destructive">{preferenceError || adapter.preferenceError}</span> : null}
        </label>
      ) : null}
      {loading ? (
        <div role="status" className="text-sm text-muted-foreground">
          Loading regions…
        </div>
      ) : regions.length ? (
        <FormBuilderMultiCombobox
          aria-label="Regions"
          values={selected}
          disabled={disabled}
          options={regions.map((region) => ({
            value: String(region.id),
            label: region.title || String(region.id),
          }))}
          placeholder="Select regions..."
          searchPlaceholder="Search regions..."
          onValuesChange={(next) => onChange(mergeRegionSelection(value, tableName, regions, next))}
        />
      ) : (
        <div className="text-sm text-muted-foreground">
          {tableName ? "No regions available." : "Choose a region collection to edit relations."}
        </div>
      )}
      {foreignCount ? (
        <div className="text-xs text-muted-foreground">
          {foreignCount} relation{foreignCount === 1 ? "" : "s"} from other region tables will be
          preserved.
        </div>
      ) : null}
      {error ? (
        <div className="grid gap-1">
          <div role="alert" className="text-xs text-destructive">
            {error}
          </div>
          <Button
            type="button"
            size="sm"
            variant="outline"
            onClick={() => setRetry((run) => run + 1)}
          >
            Retry regions
          </Button>
        </div>
      ) : null}
    </div>
  )
}
