import { zodResolver } from "@hookform/resolvers/zod"
import type { Resolver } from "react-hook-form"
import * as z from "zod"
import type { ZodSettings } from "@/lib/mapsvg-api"
import type { SchemaFormRecord } from "./types"

type JsonSchemaObject = Record<string, unknown>

export type SchemaFormValidation = {
  resolver: Resolver<SchemaFormRecord>
  configurationError: string | null
}

function isRecord(value: unknown): value is JsonSchemaObject {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value)
}

function parseRoot(settings: ZodSettings): JsonSchemaObject {
  if (settings.version !== 1) {
    throw new Error(`Unsupported zodSettings version: ${String(settings.version)}`)
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(settings.jsonSchema)
  } catch {
    throw new Error("Record validation JSON Schema is not valid JSON.")
  }

  if (!isRecord(parsed)) {
    throw new Error("Record validation JSON Schema must be an object.")
  }
  if (parsed.type !== undefined && parsed.type !== "object") {
    throw new Error("Record validation root must have type object.")
  }
  if (parsed.properties !== undefined && !isRecord(parsed.properties)) {
    throw new Error("Record validation properties must be an object.")
  }
  if (
    parsed.required !== undefined &&
    (!Array.isArray(parsed.required) || parsed.required.some((name) => typeof name !== "string"))
  ) {
    throw new Error("Record validation required must be an array of field names.")
  }

  return parsed
}

function propertyType(node: unknown): string | null {
  if (!isRecord(node)) return null
  if (typeof node.type === "string") return node.type
  if (Array.isArray(node.type)) {
    const nonNull = node.type.filter((type) => type !== "null")
    return nonNull.length === 1 && typeof nonNull[0] === "string" ? nonNull[0] : null
  }
  return null
}

const JSON_NUMBER_PATTERN = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/

function numericProjection(value: unknown): unknown {
  if (typeof value !== "string") return value
  const trimmed = value.trim()
  if (!trimmed || !JSON_NUMBER_PATTERN.test(trimmed)) return value
  const number = Number(trimmed)
  return Number.isFinite(number) ? number : value
}

/**
 * Build a validation-only view of legacy MapSVG values.
 *
 * Historical text/varchar controls expose numbers as strings. JSON Schema should
 * still be able to describe them semantically as number/integer without changing
 * the record that MapSVG persists. Empty optional numeric controls are omitted
 * from the validation projection; required ones remain empty and fail normally.
 */
export function projectRecordForValidation(
  record: SchemaFormRecord,
  jsonSchema: JsonSchemaObject,
): SchemaFormRecord {
  if (!isRecord(jsonSchema.properties)) return { ...record }

  const required = new Set(
    Array.isArray(jsonSchema.required)
      ? jsonSchema.required.filter((name): name is string => typeof name === "string")
      : [],
  )
  const projected: SchemaFormRecord = { ...record }

  for (const [name, node] of Object.entries(jsonSchema.properties)) {
    if (!Object.prototype.hasOwnProperty.call(projected, name)) continue

    const type = propertyType(node)
    if (type !== "number" && type !== "integer") continue

    const value = projected[name]
    if (value === "" && !required.has(name)) {
      delete projected[name]
      continue
    }

    projected[name] = numericProjection(value)
  }

  return projected
}

function blockingResolver(message: string): Resolver<SchemaFormRecord> {
  return async () => ({
    values: {},
    errors: {
      root: {
        type: "validation_configuration",
        message,
      },
    },
  })
}

export function createSchemaFormValidation(
  settings: ZodSettings | null | undefined,
): SchemaFormValidation | null {
  if (!settings || settings.writeValidation === "off") return null

  try {
    const jsonSchema = parseRoot(settings)
    // The checked root represents record input; raw mode returns that input unchanged.
    const validator = z.fromJSONSchema(jsonSchema as never) as z.ZodType<
      SchemaFormRecord,
      SchemaFormRecord
    >
    const baseResolver = zodResolver(validator, undefined, {
      raw: true,
    })

    const resolver: Resolver<SchemaFormRecord> = async (values, context, options) => {
      const projected = projectRecordForValidation(values, jsonSchema)
      const result = await baseResolver(projected, context, options)

      if (Object.keys(result.errors).length > 0) {
        return result
      }

      // Validation may use a projected value (for example number "12" -> 12),
      // but persistence keeps the original legacy-compatible record shape.
      return {
        values,
        errors: {},
      }
    }

    return { resolver, configurationError: null }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return {
      resolver: blockingResolver(message),
      configurationError: message,
    }
  }
}
