import { useLayoutEffect, useMemo, useRef } from "react"
import { MonacoCodeEditor } from "@/components/MonacoCodeEditor"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { FormBuilderCombobox, FormBuilderMultiCombobox } from "../FormBuilderCombobox"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import type { SchemaFieldControlProps } from "./types"
import {
  buildLegacyCheckboxValues,
  buildLegacyMultiselectValue,
  fieldOptions,
  optionValue,
  selectedOptionValues,
  type SchemaFieldOption,
} from "./value"

function inputValue(value: unknown): string {
  return value == null ? "" : String(value)
}

let nextRecordEditorId = 0

function TextControl({ field, value, disabled, onChange }: SchemaFieldControlProps) {
  return (
    <Input
      value={inputValue(value)}
      placeholder={field.placeholder == null ? undefined : String(field.placeholder)}
      readOnly={disabled}
      onChange={(event) => onChange(event.target.value)}
    />
  )
}
function IdControl({ field, value, disabled, onChange }: SchemaFieldControlProps) {
  const generated = field.auto_increment !== false
  return (
    <Input
      value={inputValue(value)}
      placeholder={field.placeholder}
      readOnly={disabled || generated}
      onChange={(event) => onChange(event.target.value)}
    />
  )
}

function TextareaControl({ field, value, disabled, onChange, recordOwner }: SchemaFieldControlProps) {
  const html = field.html === true
  const editorAvailable = typeof window !== "undefined" && !!window.MapSVG?.extensions?.get("admin.panel", "code-editor")
  const documentId = useMemo(() => `record:${field.name}:${++nextRecordEditorId}`, [recordOwner, field.name])
  const owner = useMemo(() => ({}), [recordOwner, field.name, html, disabled])
  const currentOwner = useRef<object | null>(null)
  useLayoutEffect(() => {
    currentOwner.current = owner
    return () => { if (currentOwner.current === owner) currentOwner.current = null }
  }, [owner])
  if (html && editorAvailable) return <div className="h-64 min-w-0 overflow-hidden rounded-md border" data-slot="record-html-editor">
    <MonacoCodeEditor key={documentId} documentId={documentId} language="html" value={inputValue(value)}
      options={{ readOnly: disabled, ariaLabel: String(field.label || field.name || "HTML"), tabSize: 2 }}
      onChange={next => {
        if (currentOwner.current === owner && !disabled && next !== inputValue(value)) onChange(next)
      }} />
  </div>
  return (
    <Textarea
      value={inputValue(value)}
      placeholder={field.placeholder == null ? undefined : String(field.placeholder)}
      readOnly={disabled}
      onChange={(event) => onChange(event.target.value)}
    />
  )
}

function CheckboxControl({ field, value, disabled, onChange }: SchemaFieldControlProps) {
  const checked = value === true
  const label = field.checkboxLabel == null ? "" : String(field.checkboxLabel)

  if (field.showAsSwitch !== false) {
    return (
      <div className="flex items-center gap-2">
        <Switch checked={checked} disabled={disabled} onCheckedChange={onChange} />
        {label ? <span className="text-sm">{label}</span> : null}
      </div>
    )
  }

  return (
    <div className="flex items-center gap-2">
      <Checkbox
        checked={checked}
        disabled={disabled}
        onCheckedChange={(next) => onChange(next === true)}
      />
      {label ? <span className="text-sm">{label}</span> : null}
    </div>
  )
}
function CheckboxesControl({ field, value, disabled, onChange }: SchemaFieldControlProps) {
  const selected = new Set(selectedOptionValues(value))

  return (
    <div className="grid gap-2">
      {fieldOptions(field).map((option) => {
        const optionKey = optionValue(option)
        const id = `${field.name || "field"}-${optionKey}`
        const optionDisabled = disabled || option.disabled === true || option.premium === true
        return (
          <div key={optionKey} className="flex items-center gap-2">
            <Checkbox
              id={id}
              checked={selected.has(optionKey)}
              disabled={optionDisabled}
              onCheckedChange={(checked) => {
                const next = new Set(selected)
                if (checked === true) {
                  next.add(optionKey)
                } else {
                  next.delete(optionKey)
                }
                onChange(buildLegacyCheckboxValues(field, next))
              }}
            />
            <Label htmlFor={id}>{option.label == null ? optionKey : String(option.label)}</Label>
          </div>
        )
      })}
    </div>
  )
}
function RadioControl({ field, value, disabled, onChange }: SchemaFieldControlProps) {
  return (
    <RadioGroup value={inputValue(value)} disabled={disabled} onValueChange={onChange}>
      {fieldOptions(field).map((option) => {
        const optionKey = optionValue(option)
        const id = `${field.name || "field"}-${optionKey}`
        return (
          <div key={optionKey} className="flex items-center gap-2">
            <RadioGroupItem
              id={id}
              value={optionKey}
              disabled={option.disabled === true || option.premium === true}
            />
            <Label htmlFor={id}>{option.label == null ? optionKey : String(option.label)}</Label>
          </div>
        )
      })}
    </RadioGroup>
  )
}

function selectOption(option: SchemaFieldOption) {
  const value = optionValue(option)
  return {
    value,
    label: option.label == null ? value : String(option.label),
    disabled: option.disabled === true || option.premium === true,
  }
}

function SingleSelectControl({ field, value, disabled, onChange }: SchemaFieldControlProps) {
  const options = Array.isArray(field.options) ? (field.options as SchemaFieldOption[]) : []

  return (
    <FormBuilderCombobox
      value={inputValue(value)}
      disabled={disabled}
      onValueChange={onChange}
      emptyLabel={field.type === "select" && !field.optionsGrouped ? "..." : undefined}
      options={field.optionsGrouped ? [] : options.map(selectOption)}
      groups={
        field.optionsGrouped
          ? options.map((group, index) => ({
              label: String(group.title ?? group.label ?? "Group " + (index + 1)),
              options: (group.options ?? []).map(selectOption),
            }))
          : []
      }
      searchPlaceholder="Search options..."
    />
  )
}

function MultiSelectControl({ field, value, disabled, onChange }: SchemaFieldControlProps) {
  const selected = selectedOptionValues(value)
  const options = fieldOptions(field).map(selectOption)

  return (
    <FormBuilderMultiCombobox
      values={selected}
      disabled={disabled}
      options={options}
      placeholder="Select options..."
      searchPlaceholder="Search options..."
      onValuesChange={(next) => onChange(buildLegacyMultiselectValue(field, next))}
    />
  )
}

function SelectControl(props: SchemaFieldControlProps) {
  return props.field.multiselect ? (
    <MultiSelectControl {...props} />
  ) : (
    <SingleSelectControl {...props} />
  )
}

export {
  CheckboxControl,
  CheckboxesControl,
  IdControl,
  RadioControl,
  SelectControl,
  SingleSelectControl,
  TextControl,
  TextareaControl,
}
