/** Value formats from the bundled bootstrap-datepicker locales. No legacy DOM dependency. */
const formatLanguages: Record<string, string[]> = {
  "dd.mm.yyyy": "bs de et fr-CH hy it-CH ka me mk nb no pl rs-latin rs ru sr-latin sr tr uk".split(" "),
  "dd/mm/yyyy": "ca en-GB es fr gl it nl-BE pt-BR pt vi".split(" "),
  "dd.m.yyyy": ["cs"], "d/m/yyyy": ["el"], "d/mm/yyyy": ["en-AU"],
  "yyyy-mm-dd": ["eo", "ko", "lt", "sv"], "yyyy/mm/dd": ["fa", "ja"],
  "d.m.yyyy": ["fi", "sk"], "yyyy.mm.dd": ["hu", "mn"], "dd-mm-yyyy": ["nl"],
  "yyyy年mm月dd日": ["zh-CN", "zh-TW"],
}

export function recordDateFormat(language?: string): string {
  const locale = String(language ?? "en").toLowerCase()
  const entry = Object.entries(formatLanguages).find(([, languages]) => languages.some(code => code.toLowerCase() === locale))
    ?? Object.entries(formatLanguages).find(([, languages]) => languages.includes(locale.split("-")[0]))
  return entry?.[0] ?? "mm/dd/yyyy"
}

function parseDate(value: string, pattern: string): Date | undefined {
  const tokens: string[] = []
  const escaped = pattern.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
  const regex = escaped.replace(/yyyy|dd|mm|d|m/g, token => { tokens.push(token); return token === "yyyy" ? "(\\d{4})" : "(\\d{1,2})" })
  const match = value.trim().match(new RegExp(`^${regex}$`))
  if (!match) return
  let year = 0, month = 0, day = 0
  tokens.forEach((token, index) => {
    const part = Number(match[index + 1])
    if (token === "yyyy") year = part
    else if (token.startsWith("m")) month = part
    else day = part
  })
  if (year < 1 || month < 1 || month > 12 || day < 1 || day > 31) return
  const date = new Date(0)
  date.setFullYear(year, month - 1, day)
  date.setHours(12, 0, 0, 0)
  if (date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day) return date
}

/** Prefer the field's locale for ambiguous dates; retain recognizable existing formats. */
export function readRecordDate(value: string, language?: string): { date?: Date; format: string } {
  const preferred = recordDateFormat(language)
  for (const format of new Set([preferred, "yyyy-mm-dd", ...Object.keys(formatLanguages), "mm/dd/yyyy"])) {
    const date = parseDate(value, format)
    if (date) return { date, format }
  }
  return { format: preferred }
}

export function writeRecordDate(date: Date, format: string): string {
  const parts: Record<string, string> = {
    yyyy: String(date.getFullYear()).padStart(4, "0"), mm: String(date.getMonth() + 1).padStart(2, "0"),
    dd: String(date.getDate()).padStart(2, "0"), m: String(date.getMonth() + 1), d: String(date.getDate()),
  }
  return format.replace(/yyyy|dd|mm|d|m/g, token => parts[token])
}
