import { Field, FieldContent, FieldDescription, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Switch } from "@/components/ui/switch"
import type { ZodSettings } from "@/lib/mapsvg-api"
import type { FormFieldData } from "../../../../../mapsvg/FormBuilder/FieldDefinitions"
import { FormBuilderChoice } from "../FormBuilderChoice"
import {
  getFieldValidationNode,
  getFieldValidationType,
  isFieldNullable,
  isFieldRequired,
  setFieldNullable,
  setFieldRequired,
  setFieldValidationKeyword,
  setFieldValidationType,
  suggestedValidationType,
  type FieldValidationType,
} from "./validation"

type Props = {
  field: FormFieldData
  zodSettings: ZodSettings | null
  onChange: (settings: ZodSettings | null) => void
}

function NumericRule({
  label,
  value,
  min,
  integer,
  onChange,
}: {
  label: string
  value: unknown
  min?: number
  integer?: boolean
  onChange: (value: number | undefined) => void
}) {
  return (
    <Field>
      <FieldContent>
        <FieldLabel>{label}</FieldLabel>
        <Input
          type="number"
          min={min}
          step={integer ? 1 : "any"}
          value={typeof value === "number" ? value : ""}
          onChange={(event) => {
            const raw = event.target.value
            if (raw === "") {
              onChange(undefined)
              return
            }
            const next = Number(raw)
            if (!Number.isFinite(next)) return
            onChange(integer ? Math.trunc(next) : next)
          }}
        />
      </FieldContent>
    </Field>
  )
}

function BooleanRule({
  label,
  checked,
  disabled,
  description,
  onChange,
}: {
  label: string
  checked: boolean
  disabled?: boolean
  description?: string
  onChange: (checked: boolean) => void
}) {
  return (
    <Field orientation="horizontal">
      <FieldContent>
        <FieldLabel>{label}</FieldLabel>
        {description ? <FieldDescription>{description}</FieldDescription> : null}
      </FieldContent>
      <Switch checked={checked} disabled={disabled} onCheckedChange={onChange} />
    </Field>
  )
}

function choiceDescription(field: FormFieldData): string | null {
  if (
    field.type === "radio" ||
    field.type === "status" ||
    (field.type === "select" && field.multiselect !== true)
  ) {
    return "Allowed values are kept in sync with this field's options."
  }
  if (field.type === "checkboxes") {
    return "Allowed item values are kept in sync with this field's options."
  }
  return null
}

export function ValidationSettings({ field, zodSettings, onChange }: Props) {
  const name = String(field.name ?? "")
  const node = name ? getFieldValidationNode(zodSettings, name) : null
  const type = getFieldValidationType(node)
  const enabled = node !== null
  const generatedId = field.type === "id" && field.auto_increment !== false
  const choiceHelp = choiceDescription(field)

  return (
    <div className="grid gap-4 border-t pt-5">
      <div>
        <div className="text-sm font-medium">Validation</div>
        <div className="mt-1 text-xs text-muted-foreground">
          Stored as standard JSON Schema and shared by JavaScript and PHP runtimes.
        </div>
      </div>

      <BooleanRule
        label="Validate value"
        checked={enabled}
        disabled={!name || generatedId}
        description={
          generatedId
            ? "Generated IDs are validated by storage, not by the record form."
            : "Enable semantic validation for this field."
        }
        onChange={(checked) =>
          onChange(
            setFieldValidationType(
              zodSettings,
              field,
              checked ? suggestedValidationType(field) : null,
            ),
          )
        }
      />

      {enabled ? (
        <>
          <Field>
            <FieldContent>
              <FieldLabel>Type</FieldLabel>
              <FormBuilderChoice
                aria-label="Validation type"
                value={type ?? "custom"}
                onValueChange={(value) =>
                  onChange(setFieldValidationType(zodSettings, field, value as FieldValidationType))
                }
                options={[
                  ...(type === "custom"
                    ? [{ value: "custom", label: "Custom / advanced", disabled: true }]
                    : []),
                  { value: "string", label: "String" },
                  { value: "number", label: "Number" },
                  { value: "integer", label: "Integer" },
                  { value: "boolean", label: "Boolean" },
                  { value: "array", label: "Array" },
                  { value: "object", label: "Object" },
                ]}
              />
              {type === "custom" ? (
                <FieldDescription>
                  This property uses advanced JSON Schema. Choose a basic type to edit common rules;
                  unknown keywords are preserved.
                </FieldDescription>
              ) : null}
            </FieldContent>
          </Field>

          <BooleanRule
            label="Required"
            checked={isFieldRequired(zodSettings, name)}
            disabled={generatedId}
            onChange={(required) => onChange(setFieldRequired(zodSettings, name, required))}
          />

          <BooleanRule
            label="Nullable"
            checked={isFieldNullable(node)}
            disabled={type === "custom"}
            onChange={(nullable) => onChange(setFieldNullable(zodSettings, name, nullable))}
          />

          {choiceHelp ? <FieldDescription>{choiceHelp}</FieldDescription> : null}

          {type === "string" ? (
            <>
              <NumericRule
                label="Minimum length"
                min={0}
                integer
                value={node?.minLength}
                onChange={(value) =>
                  onChange(setFieldValidationKeyword(zodSettings, name, "minLength", value))
                }
              />
              <NumericRule
                label="Maximum length"
                min={0}
                integer
                value={node?.maxLength}
                onChange={(value) =>
                  onChange(setFieldValidationKeyword(zodSettings, name, "maxLength", value))
                }
              />
              <Field>
                <FieldContent>
                  <FieldLabel>Format</FieldLabel>
                  <FormBuilderChoice
                    aria-label="Validation format"
                    value={typeof node?.format === "string" ? node.format : "none"}
                    onValueChange={(format) =>
                      onChange(
                        setFieldValidationKeyword(
                          zodSettings,
                          name,
                          "format",
                          format === "none" ? undefined : format,
                        ),
                      )
                    }
                    options={[
                      { value: "none", label: "None" },
                      { value: "email", label: "Email" },
                      { value: "uri", label: "URI" },
                    ]}
                  />
                </FieldContent>
              </Field>
              <Field>
                <FieldContent>
                  <FieldLabel>Pattern</FieldLabel>
                  <Input
                    value={typeof node?.pattern === "string" ? node.pattern : ""}
                    placeholder="Regular expression"
                    onChange={(event) =>
                      onChange(
                        setFieldValidationKeyword(
                          zodSettings,
                          name,
                          "pattern",
                          event.target.value || undefined,
                        ),
                      )
                    }
                  />
                </FieldContent>
              </Field>
            </>
          ) : null}

          {type === "number" || type === "integer" ? (
            <>
              <NumericRule
                label="Minimum"
                value={node?.minimum}
                onChange={(value) =>
                  onChange(setFieldValidationKeyword(zodSettings, name, "minimum", value))
                }
              />
              <NumericRule
                label="Maximum"
                value={node?.maximum}
                onChange={(value) =>
                  onChange(setFieldValidationKeyword(zodSettings, name, "maximum", value))
                }
              />
              <NumericRule
                label="Multiple of"
                value={node?.multipleOf}
                onChange={(value) =>
                  onChange(setFieldValidationKeyword(zodSettings, name, "multipleOf", value))
                }
              />
            </>
          ) : null}

          {type === "array" ? (
            <>
              <NumericRule
                label="Minimum items"
                min={0}
                integer
                value={node?.minItems}
                onChange={(value) =>
                  onChange(setFieldValidationKeyword(zodSettings, name, "minItems", value))
                }
              />
              <NumericRule
                label="Maximum items"
                min={0}
                integer
                value={node?.maxItems}
                onChange={(value) =>
                  onChange(setFieldValidationKeyword(zodSettings, name, "maxItems", value))
                }
              />
            </>
          ) : null}
        </>
      ) : null}
    </div>
  )
}
