import { adminRestFetch } from "@/lib/admin-rest-fetch"
import { resourceApiUrl } from "@/lib/resource-api-url"
import { getAdminParams } from "@/lib/admin-params"

export type MapSvgImage = {
  thumbnail?: string
  medium?: string
  large?: string
  full?: string
  sizes?: Record<string, { width?: number; height?: number }>
  caption?: string
  description?: string
  [key: string]: unknown
}

export type MapSvgPost = {
  id: number | string
  post_title: string
  post_content?: string
  url?: string
  [key: string]: unknown
}

export type MapSvgRegionOption = {
  id: string
  title: string
}

export type MapSvgRegionRef = MapSvgRegionOption & {
  tableName: string
}

export interface MediaPickerAdapter {
  pickImages(): Promise<MapSvgImage[]>
}

export interface PostAdapter {
  listPostTypes(): Promise<string[]>
  searchPosts(postType: string, search: string): Promise<MapSvgPost[]>
}

export interface RegionAdapter {
  tableName: string
  sources?: Array<{ tableName: string; title: string }>
  rememberSource?(tableName: string): Promise<void>
  preferenceKey?: string
  preferenceError?: string
  listRegions(tableName?: string): Promise<MapSvgRegionOption[]>
}

export type ComplexFieldAdapters = {
  media?: MediaPickerAdapter
  posts?: PostAdapter
  regions?: RegionAdapter
}

export const COMPLEX_FIELD_CONTEXT_KEY = "complexFieldAdapters"
export function adaptersFromContext(context?: Record<string, unknown>): ComplexFieldAdapters {
  const value = context?.[COMPLEX_FIELD_CONTEXT_KEY]
  return value && typeof value === "object" ? (value as ComplexFieldAdapters) : {}
}

function normalizeProtocol(url: unknown): string | undefined {
  if (typeof url !== "string" || !url) {
    return undefined
  }
  return url.replace(/^https?:\/\//, "//")
}

export function normalizeWordPressAttachment(attachment: Record<string, any>): MapSvgImage {
  const image: MapSvgImage = { sizes: {} }
  const sizes = attachment.sizes && typeof attachment.sizes === "object" ? attachment.sizes : {}

  Object.entries(sizes).forEach(([type, raw]) => {
    if (!raw || typeof raw !== "object") {
      return
    }
    const size = raw as Record<string, unknown>
    const url = normalizeProtocol(size.url)
    if (url) {
      image[type] = url
      image.sizes![type] = {
        width: typeof size.width === "number" ? size.width : undefined,
        height: typeof size.height === "number" ? size.height : undefined,
      }
    }
  })

  if (!image.full) {
    image.full = normalizeProtocol(attachment.url)
    if (image.full) {
      image.sizes!.full = {
        width: typeof attachment.width === "number" ? attachment.width : undefined,
        height: typeof attachment.height === "number" ? attachment.height : undefined,
      }
    }
  }
  if (!image.thumbnail && image.full) {
    image.thumbnail = image.full
    image.sizes!.thumbnail = { ...(image.sizes!.full ?? {}) }
  }
  if (!image.medium && image.full) {
    image.medium = image.full
    image.sizes!.medium = { ...(image.sizes!.full ?? {}) }
  }

  if (typeof attachment.caption === "string") {
    image.caption = attachment.caption
  }
  if (typeof attachment.description === "string") {
    image.description = attachment.description
  }

  return image
}

export function createWordPressMediaPicker(): MediaPickerAdapter {
  return {
    async pickImages() {
      const wp = (window as any).wp
      if (!wp?.media) {
        throw new Error("WordPress media library is unavailable.")
      }

      return await new Promise<MapSvgImage[]>((resolve) => {
        const frame = wp.media({
          title: "Select images",
          library: { type: "image" },
          multiple: true,
        })
        let settled = false

        const finish = (images: MapSvgImage[]) => {
          if (settled) return
          settled = true
          resolve(images)
        }

        frame.on("select", () => {
          const selection = frame.state().get("selection").toJSON()
          finish(
            Array.isArray(selection)
              ? selection.map((item: Record<string, any>) => normalizeWordPressAttachment(item))
              : [],
          )
        })
        frame.on("close", () => {
          // WordPress Toolbar.Select closes the frame before it triggers the
          // selection event. Defer cancellation so a real selection wins the
          // race; an actual cancel/escape still resolves with an empty list.
          window.setTimeout(() => finish([]), 0)
        })
        frame.open()
      })
    },
  }
}
async function apiGet(path: string, query?: Record<string, string>): Promise<unknown> {
  const params = getAdminParams()
  const url = resourceApiUrl(params.apiUrl, path.startsWith("/") ? path : `/${path}`)
  const queryString = new URLSearchParams(query).toString()
  const response = await adminRestFetch(
    url + (queryString ? (url.includes("?") ? "&" : "?") + queryString : ""),
    {
      credentials: "same-origin",
      headers: {
        Accept: "application/json",
        "X-WP-Nonce": params.nonce,
      },
    },
  )

  if (!response.ok) {
    throw new Error(`MapSVG API ${response.status}: ${path}`)
  }
  return await response.json()
}

export function createWordPressPostAdapter(): PostAdapter {
  return {
    async listPostTypes() {
      const response = await apiGet("/post-types/")
      return Array.isArray(response)
        ? response.filter((item): item is string => typeof item === "string")
        : []
    },

    async searchPosts(postType: string, search: string) {
      if (!search.trim()) {
        return []
      }
      const response = (await apiGet("/posts", {
        "filters[post_type]": postType,
        search: search.trim(),
      })) as { posts?: unknown }

      return Array.isArray(response.posts)
        ? response.posts.filter((post): post is MapSvgPost =>
            Boolean(
              post &&
              typeof post === "object" &&
              (typeof (post as MapSvgPost).id === "number" ||
                typeof (post as MapSvgPost).id === "string") &&
              typeof (post as MapSvgPost).post_title === "string",
            ),
          )
        : []
    },
  }
}
export function createStaticRegionAdapter(
  tableName: string,
  regions: Array<{ id: string | number; title?: string }>,
): RegionAdapter {
  return {
    tableName,
    async listRegions() {
      return regions.map((region) => ({
        id: String(region.id),
        title: region.title ? String(region.title) : String(region.id),
      }))
    },
  }
}

export function createMapRegionAdapter(map: {
  regions?: ArrayLike<{ id: string | number; title?: string }>
  regionsRepository?: {
    getSchema?: () => { name?: string }
  }
}): RegionAdapter {
  const tableName = String(map.regionsRepository?.getSchema?.().name ?? "")
  return {
    tableName,
    async listRegions() {
      return Array.from(map.regions ?? []).map((region) => ({
        id: String(region.id),
        title: region.title ? String(region.title) : String(region.id),
      }))
    },
  }
}
