import { Trash } from "lucide-react"
import {
  ValueEditor,
  useValueSelector,
  type ValueEditorProps,
  type ActionProps,
  type ValueSelectorProps,
  type FullOption,
} from "react-querybuilder"
import { FormBuilderMultiCombobox } from "@/components/form-builder/FormBuilderCombobox"
import { FormBuilderChoice } from "@/components/form-builder/FormBuilderChoice"
import { Button } from "@/components/ui/button"

function QuerySelector(props: ValueSelectorProps) {
  // Keep React Query Builder's single/list representation and conversion ownership.
  const { val, onChange } = useValueSelector(props)
  const options = props.options
    .flatMap((option) => ("options" in option ? (option.options as FullOption[]) : [option]))
    .map((option) => ({
      value: String(option.name),
      label: String(option.label),
      disabled: option.disabled,
    }))
  const common = {
    options,
    disabled: props.disabled,
    className: props.className + " w-auto min-w-28 max-w-full",
    title: props.title,
    "aria-label": props.title,
    "data-testid": props.testID,
  }
  if (props.multiple) {
    return (
      <FormBuilderMultiCombobox
        {...common}
        values={Array.isArray(val) ? val : []}
        onValuesChange={onChange}
      />
    )
  }
  // An unsupported persisted value must stay visible and unchanged until the user repairs it.
  const value = String(val ?? "")
  if (!options.some((option) => option.value === value))
    options.unshift({ value, label: value || "Select...", disabled: false })
  const empty = options.find((option) => option.value === "")
  return (
    <FormBuilderChoice
      {...common}
      options={options.filter((option) => option.value !== "")}
      emptyLabel={empty?.label}
      value={value}
      onValueChange={onChange}
    />
  )
}

function QueryValueEditor(props: ValueEditorProps) {
  const type =
    props.type === "select" && (props.operator === "in" || props.operator === "notIn")
      ? "multiselect"
      : props.inputType === "checkbox"
        ? "checkbox"
        : props.type
  return <ValueEditor {...props} type={type} />
}

function RemoveRule(props: ActionProps) {
  return (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      className={props.className}
      title={props.title}
      aria-label={props.title || "Remove rule"}
      data-testid={props.testID}
      disabled={props.disabled}
      onClick={(event) => props.handleOnClick(event)}
    >
      <Trash className="size-4" aria-hidden="true" />
    </Button>
  )
}

export const queryBuilderControls = {
  fieldSelector: QuerySelector,
  operatorSelector: QuerySelector,
  combinatorSelector: QuerySelector,
  valueSourceSelector: QuerySelector,
  valueSelector: QuerySelector,
  valueEditor: QueryValueEditor,
  removeRuleAction: RemoveRule,
}
