import type { FormFieldData } from "../../../../../mapsvg/FormBuilder/FieldDefinitions"
import {
  CheckboxControl,
  CheckboxesControl,
  IdControl,
  RadioControl,
  SelectControl,
  SingleSelectControl,
  TextControl,
  TextareaControl,
} from "./controls"
import { DateControl, ColorControl } from "./specialControls"
import type { SchemaFieldControlRegistry } from "./types"

export const simpleSchemaFieldControls: SchemaFieldControlRegistry = {
  text: TextControl,
  // Persisted compatibility types are not new field-builder definitions.
  number: TextControl,
  datetime: TextControl,
  boolean: CheckboxControl,
  textarea: TextareaControl,
  checkbox: CheckboxControl,
  checkboxes: CheckboxesControl,
  radio: RadioControl,
  select: SelectControl,
  date: DateControl,
  status: SingleSelectControl,
  title: TextControl,
  colorpicker: ColorControl,
  id: IdControl,
}

export function hasSimpleSchemaFieldControl(field: FormFieldData): boolean {
  return Boolean(simpleSchemaFieldControls[field.type])
}
