import { useEffect, useState } from "react"
import { Field, FieldContent, FieldDescription, FieldLabel } from "@/components/ui/field"
import { FormBuilderCombobox } from "../FormBuilderCombobox"
import { CommonSettings, SearchableSettings, TextSetting } from "../schema-builder/settings"
import type { SchemaFieldSettingsProps } from "../schema-builder/types"
import { adaptersFromContext } from "./adapters"

export function ImageFieldSettings(props: SchemaFieldSettingsProps) {
  return (
    <CommonSettings {...props}>
      <TextSetting
        label="Button text"
        value={props.field.button_text}
        onChange={(button_text) => props.onPatch({ button_text })}
      />
    </CommonSettings>
  )
}

export function RegionFieldSettings(props: SchemaFieldSettingsProps) {
  return (
    <CommonSettings {...props}>
      <SearchableSettings field={props.field} onPatch={props.onPatch} />
      <FieldDescription>
        Region values are stored as references with region ID, title and table name.
      </FieldDescription>
    </CommonSettings>
  )
}

export function PostFieldSettings(props: SchemaFieldSettingsProps) {
  const posts = adaptersFromContext(props.context).posts
  const [postTypes, setPostTypes] = useState<string[]>([])
  const [error, setError] = useState("")

  useEffect(() => {
    let active = true
    if (!posts) {
      setPostTypes([])
      return
    }

    posts
      .listPostTypes()
      .then((types) => {
        if (!active) return
        setPostTypes(types)
      })
      .catch((err) => {
        if (active) {
          setError(err instanceof Error ? err.message : "Unable to load post types.")
        }
      })

    return () => {
      active = false
    }
  }, [posts])
  return (
    <CommonSettings {...props}>
      <Field>
        <FieldContent>
          <FieldLabel>Post type</FieldLabel>
          {postTypes.length ? (
            <FormBuilderCombobox
              value={
                typeof props.field.post_type === "string" ? props.field.post_type : postTypes[0]
              }
              onValueChange={(post_type) => props.onPatch({ post_type })}
              options={postTypes.map((postType) => ({
                value: postType,
                label: postType,
              }))}
              searchPlaceholder="Search post types..."
            />
          ) : (
            <TextSetting
              label=""
              value={props.field.post_type}
              onChange={(post_type) => props.onPatch({ post_type })}
            />
          )}
          <FieldDescription>WordPress post type used by the record post search.</FieldDescription>
          {!posts ? (
            <FieldDescription>
              Post adapter is not connected; enter the post type manually.
            </FieldDescription>
          ) : null}
          {error ? <div className="text-xs text-destructive">{error}</div> : null}
        </FieldContent>
      </Field>
    </CommonSettings>
  )
}
