/** A fresh surface projection, never an App snapshot or a data/authoring runtime. */
export function locationPickerOptions(surface: Record<string, unknown>): Record<string, unknown> {
  const result = Object.fromEntries(["source", "width", "height", "viewBox", "colors", "googleMaps"].filter(key => surface[key] !== undefined).map(key => [key, structuredClone(surface[key])]))
  return {
    ...result, useShadowRoot: true, responsive: true,
    database: { on: false, loadOnStart: false, autoRefetch: { on: false }, regionsAutoRefetch: { on: false } },
    menu: { on: false }, filters: { on: false }, tooltips: { on: false }, popovers: { on: false },
    legend: { on: false }, layersControl: { on: false }, choropleth: { on: false },
    regionDataRules: { on: false }, events: {}, middlewares: {}, galleries: [],
    controls: { zoom: false, zoomReset: false, userLocation: false, previousMap: false },
    zoom: { on: true, mousewheel: true, limit: [0, 22] }, scroll: { on: true }, disableAll: true,
    containers: Object.fromEntries(["leftSidebar", "rightSidebar", "header", "footer"].map(id => [id, { on: false }])),
    // A non-empty registry avoids migrating legacy Details/Directory components.
    nodes: [{ id: "map", type: "map", title: "Map", children: [], settings: {} }],
    layout: { mountMode: "legacy", deletedNodeTypes: ["layers", "legend", "mobileToolbar"] }, scenes: [],
  }
}
