export type LocationPoint = { lat: number; lng: number }
export type SvgPoint = { x: number; y: number }

export type LocationValue = {
  img?: string
  imagePath?: string
  markerImagePath?: string
  geoPoint?: LocationPoint
  svgPoint?: SvgPoint
  address?: Record<string, any>
  [key: string]: any
}

export type LocationSearchResult = {
  formatted_address: string
  address_components?: Array<{
    long_name: string
    short_name?: string
    types: string[]
  }>
  geometry?: {
    bounds?: unknown
    viewport?: unknown
    location?: {
      lat: number | (() => number)
      lng: number | (() => number)
    }
  }
}

export type MarkerImageOption = {
  relativeUrl: string
  url?: string
  file?: string
  folder?: string
}

export interface LocationFieldAdapter {
  isGeo: boolean
  picker?: { mapId: number; rememberMap: (id: number) => Promise<void>; error?: string }
  markerDefaults?: { image?: string; rememberImage: (path: string) => Promise<void> }
  hasMapInteraction?: boolean
  search(query: string, language?: string): Promise<LocationSearchResult[]>
  markerImages(): MarkerImageOption[]
  uploadMarker?(file: File): Promise<MarkerImageOption>
  setDefaultMarkerPath?(path: string): void
  getMarkerFields?(): Promise<string[]>
  getMarkerFieldOptions?(
    fieldName: string,
  ): Promise<Array<{ label: string; value: string | number }>>
  bind(onChange: (value: LocationValue | null) => void): () => void
  sync(value: LocationValue | null): void
}

export const LOCATION_FIELD_CONTEXT_KEY = "locationFieldAdapter"

export function locationAdapterFromContext(
  context?: Record<string, unknown>,
): LocationFieldAdapter | undefined {
  const value = context?.[LOCATION_FIELD_CONTEXT_KEY]
  return value && typeof value === "object" ? (value as LocationFieldAdapter) : undefined
}
