import { useCallback, useRef, useState, type DragEvent } from "react"

/** Native list sorting shared with SchemaBuilder; each mounted list owns its drag. */
export function useDragSort<T extends string | number>(move: (from: T, to: T) => void) {
  const source = useRef<T | null>(null)
  const [dragged, setDragged] = useState<T | null>(null)
  const [target, setTarget] = useState<T | null>(null)
  const cancel = useCallback(() => {
    source.current = null
    setDragged(null)
    setTarget(null)
  }, [])
  const itemProps = (id: T) => ({
    draggable: true,
    onDragStart(event: DragEvent<HTMLElement>) {
      event.stopPropagation()
      source.current = id
      setDragged(id)
      event.dataTransfer.effectAllowed = "move"
      event.dataTransfer.setData("text/plain", String(id))
    },
    onDragOver(event: DragEvent<HTMLElement>) {
      if (source.current === null) return
      event.preventDefault()
      event.stopPropagation()
      event.dataTransfer.dropEffect = "move"
      setTarget(id)
    },
    onDrop(event: DragEvent<HTMLElement>) {
      if (source.current === null) return
      event.preventDefault()
      event.stopPropagation()
      const from = source.current
      cancel()
      if (from !== id) move(from, id)
    },
    onDragEnd: cancel,
  })
  return { itemProps, dragged, target, cancel }
}
