import { useLayoutEffect, useState, type ReactNode } from "react"
import { ChevronDown, ImageIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { getAdminParams } from "@/lib/admin-params"
import { useAdminCatalog } from "@/lib/use-admin-catalog"

export function MarkerImagePicker({ value, images, label, onChange, defaultImage, disabled = false, showChevron = false, resetKey, footer, trigger = "image" }: { value: string; images: string[]; label: string; onChange: (image: string) => void; defaultImage?: string; disabled?: boolean; showChevron?: boolean; resetKey?: object; footer?: ReactNode; trigger?: "image" | "link" }) {
  const [open, setOpen] = useState(false)
  const catalog = useAdminCatalog("markers", open, getAdminParams().markerImages)
  const available = [...new Set([...images, ...catalog.files.map(file => file.relativeUrl).filter(Boolean)])]
  useLayoutEffect(() => { setOpen(false) }, [resetKey, disabled, value])
  const displayed = value || defaultImage
  const select = (image: string) => { if (!disabled) onChange(image); setOpen(false) }
  return <Popover open={open} onOpenChange={setOpen}>
    <PopoverTrigger asChild>{trigger === "link" ? <Button type="button" variant="link" size="sm" aria-label={label} disabled={disabled} className="h-auto w-fit justify-start p-0 font-normal">{label}</Button> : <Button type="button" variant="outline" size={showChevron ? "default" : "icon"} aria-label={label} disabled={disabled} className={showChevron ? "h-auto w-fit py-1.5" : "p-1"}>
      {displayed ? <img src={displayed} alt="" className="max-h-5 max-w-5 object-contain" /> : <ImageIcon />}
      {showChevron ? <ChevronDown className="size-3 text-muted-foreground" /> : null}
    </Button>}</PopoverTrigger>
    <PopoverContent align="start" aria-label={`${label} gallery`} className="w-72 space-y-2 p-2" onWheel={event => event.stopPropagation()}>
      {defaultImage ? <button type="button" aria-label="Use default marker image" aria-pressed={!value} className="flex w-full items-center gap-2 rounded border p-2 text-xs hover:bg-accent aria-pressed:border-primary" onClick={() => select("")}>
        <span className="flex size-8 shrink-0 items-center justify-center"><img src={defaultImage} alt="" className="max-h-8 max-w-8 object-contain" /></span>
        Default marker image
      </button> : null}
      <div className="grid max-h-64 grid-cols-6 gap-1 overflow-auto">
        {available.map(image => <button key={image} type="button" aria-label={`Use marker ${image}`} aria-pressed={value === image} className="flex size-10 items-center justify-center rounded border p-1 hover:bg-accent aria-pressed:border-primary" onClick={() => select(image)}><img src={image} alt="" className="max-h-8 max-w-8 object-contain" /></button>)}
        {catalog.loading ? <p role="status" className="col-span-6 text-xs text-muted-foreground">Loading marker images…</p> : null}
        {catalog.error ? <div role="alert" className="col-span-6 text-xs text-destructive">{catalog.error} <Button type="button" variant="link" onClick={catalog.retry}>Retry</Button></div> : null}
        {!available.length && !catalog.loading && !catalog.error ? <p className="col-span-6 text-xs text-muted-foreground">Upload a marker image to add it here.</p> : null}
      </div>
      {footer ? <div className="border-t pt-2">{footer}</div> : null}
    </PopoverContent>
  </Popover>
}
