import { ArrowDownAZIcon, ArrowUpZAIcon, PlusIcon, Trash2Icon } from "lucide-react"
import { RadioGroup as RadioGroupPrimitive } from "radix-ui"
import { Button } from "@/components/ui/button"
import { RadioGroup } from "@/components/ui/radio-group"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { SettingsChoice } from "@/components/settings-form/SettingsChoice"
import type { BindingOrder } from "../../../../mapsvg/Map/pageBindings"

const directions = [
  { value: "asc", label: "Ascending", Icon: ArrowDownAZIcon },
  { value: "desc", label: "Descending", Icon: ArrowUpZAIcon },
] as const

export function QueryOrderEditor({ value, fields, onChange }: {
  value: BindingOrder | undefined
  fields: Array<{ value: string; label: string }>
  onChange: (next: BindingOrder) => void
}) {
  const rows = value ?? []
  return <div className="grid min-w-0 gap-2" aria-label="Sort order">
    {rows.map((row, index) => {
      const [name, direction] = Object.entries(row)[0] ?? ["", "asc"]
      const patch = (field: string, order: "asc" | "desc") => onChange(rows.map((item, i) => i === index ? { [field]: order } : item))
      return <div key={index} className="flex min-w-0 items-center gap-1">
        <div className="min-w-0 flex-1"><SettingsChoice aria-label={`Sort field ${index + 1}`} value={name}
          options={fields.some(field => field.value === name) ? fields : [...fields, { value: name, label: name }]}
          onValueChange={field => patch(field, direction)} /></div>
        <RadioGroup aria-label={`Sort direction ${index + 1}`} value={direction}
          orientation="horizontal"
          className="flex shrink-0 gap-0.5 rounded-md bg-muted p-0.5"
          onValueChange={order => patch(name, order as "asc" | "desc")}>
          {directions.map(({ value, label, Icon }) => (
            <Tooltip key={value}>
              <TooltipTrigger asChild>
                <RadioGroupPrimitive.Item asChild value={value}>
                  <Button type="button" variant="ghost" size="icon-xs" aria-label={label}
                    className="text-muted-foreground aria-[checked=true]:bg-background aria-[checked=true]:text-foreground aria-[checked=true]:shadow-xs">
                    <Icon />
                  </Button>
                </RadioGroupPrimitive.Item>
              </TooltipTrigger>
              <TooltipContent>{label}</TooltipContent>
            </Tooltip>
          ))}
        </RadioGroup>
        <Button variant="ghost" size="icon-xs" aria-label={`Remove sort ${index + 1}`} onClick={() => onChange(rows.filter((_, i) => i !== index))}><Trash2Icon /></Button>
      </div>
    })}
    <Button variant="outline" size="xs" className="justify-self-start" disabled={!fields.length || rows.length >= 8}
      onClick={() => onChange([...rows, { [fields[0].value]: "asc" }])}><PlusIcon />Add sort</Button>
  </div>
}
