import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react"
import { queryContentKey } from "@/components/database/globalQueryDraft"
import { fetchCollectionEditorDefaults, saveCollectionEditorDefaults, type CollectionEditorDefaults, type DataSchema } from "./mapsvg-api"

/** Editor preference refreshes must not retire unsaved record or Fields drafts. */
export function recordSchemaKey(schema: DataSchema | null): string {
  if (!schema) return queryContentKey(schema)
  const { editor: _editor, ...bindings } = schema.bindings ?? {}
  return queryContentKey({ ...schema, bindings: Object.keys(bindings).length ? bindings : null })
}

export function useCollectionEditorDefaults(schema: DataSchema | null) {
  const id = schema?.id == null ? undefined : String(schema.id)
  const owner = useMemo(() => ({}), [id])
  const active = useRef<object | null>(owner)
  useLayoutEffect(() => { active.current = owner; return () => { if (active.current === owner) active.current = null } }, [owner])
  const revision = useRef(0)
  const queue = useRef(Promise.resolve())
  const [state, setState] = useState<{ owner: object; defaults: CollectionEditorDefaults; error: string }>({ owner, defaults: schema?.bindings?.editor ?? {}, error: "" })
  const defaults = state.owner === owner ? state.defaults : schema?.bindings?.editor ?? {}
  useEffect(() => {
    const controller = new AbortController()
    const start = revision.current
    if (id == null || !["object", "post", "api"].includes(schema?.type ?? "object")) return
    void fetchCollectionEditorDefaults(id, controller.signal).then(next => {
      if (!controller.signal.aborted && active.current === owner && revision.current === start) setState({ owner, defaults: next, error: "" })
    }).catch(error => {
      if (!controller.signal.aborted && active.current === owner) setState(previous => ({ owner, defaults: previous.owner === owner ? previous.defaults : schema?.bindings?.editor ?? {}, error: error instanceof Error ? error.message : "Could not load editor preferences." }))
    })
    return () => controller.abort()
  }, [id, owner])
  const remember = useCallback((patch: CollectionEditorDefaults): Promise<void> => {
    if (id == null) return Promise.reject(new Error("Collection is unavailable."))
    revision.current++
    setState(previous => ({ owner, defaults: { ...(previous.owner === owner ? previous.defaults : schema?.bindings?.editor), ...patch }, error: "" }))
    const task = queue.current.catch(() => undefined).then(() => saveCollectionEditorDefaults(id, patch))
    queue.current = task.catch(error => {
      if (active.current === owner) setState(previous => ({ ...previous, error: error instanceof Error ? error.message : "Could not remember editor choice." }))
    })
    return task
  }, [id, owner])
  return { defaults, remember, error: state.owner === owner ? state.error : "" }
}
