import type { FormFieldData } from "../../../../../mapsvg/FormBuilder/FieldDefinitions"

export type DistanceOption = {
  value: string
  default?: boolean
  [key: string]: any
}

export function filterBoolean(value: unknown): boolean {
  if (value === true || value === 1) return true
  if (typeof value === "string") {
    return ["1", "true", "yes", "on"].includes(value.toLowerCase())
  }
  return false
}

export function distanceOptions(field: FormFieldData): DistanceOption[] {
  return Array.isArray(field.options)
    ? field.options.map((option) => ({
        ...option,
        value: String(option?.value ?? ""),
        default: filterBoolean(option?.default),
      }))
    : []
}

export function normalizedDistanceOptions(options: DistanceOption[]): DistanceOption[] {
  const nonEmpty = options
    .filter((option) => option.value.trim() !== "")
    .map((option) => ({
      ...option,
      value: option.value.trim(),
      default: filterBoolean(option.default),
    }))

  let defaultSeen = false
  nonEmpty.forEach((option) => {
    if (option.default && !defaultSeen) {
      defaultSeen = true
    } else if (option.default) {
      option.default = false
    }
  })
  if (nonEmpty.length && !defaultSeen) {
    nonEmpty[0].default = true
  }
  return nonEmpty
}

export function distanceOptionsPatch(
  field: FormFieldData,
  options: DistanceOption[],
): Record<string, any> {
  const normalized = normalizedDistanceOptions(options)
  const patch: Record<string, any> = { options: normalized }

  if (field.distanceControl === "none" && normalized.length) {
    patch.distanceDefault =
      normalized.find((option) => option.default)?.value ?? normalized[0].value
  }
  return patch
}
