import { useEffect, useState } from "react"
import { Plus, Trash2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Field, FieldContent, FieldDescription, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { FormBuilderChoice } from "../FormBuilderChoice"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { CommonSettings, SwitchSetting, TextSetting } from "../schema-builder/settings"
import type { SchemaFieldSettingsProps } from "../schema-builder/types"
import { FILTER_COUNTRIES } from "./countries"
import {
  distanceOptions,
  distanceOptionsPatch,
  filterBoolean,
  normalizedDistanceOptions,
  type DistanceOption,
} from "./model"
function DistanceOptionsSetting({
  field,
  onPatch,
}: Pick<SchemaFieldSettingsProps, "field" | "onPatch">) {
  const [rows, setRows] = useState<DistanceOption[]>(() => distanceOptions(field))
  const [newValue, setNewValue] = useState("")

  useEffect(() => {
    setRows(distanceOptions(field))
  }, [field])

  const commit = (next: DistanceOption[]) => {
    const normalized = normalizedDistanceOptions(next)
    setRows(normalized)
    onPatch(distanceOptionsPatch(field, normalized))
  }

  const setDefault = (index: number) => {
    commit(
      rows.map((row, rowIndex) => ({
        ...row,
        default: rowIndex === index,
      })),
    )
  }

  const updateValue = (index: number, value: string) => {
    setRows((current) =>
      current.map((row, rowIndex) => (rowIndex === index ? { ...row, value } : row)),
    )
  }

  return (
    <Field>
      <FieldContent>
        <FieldLabel>Distances list</FieldLabel>
        <div className="grid gap-2 rounded-md border p-3">
          {rows.map((row, index) => (
            <div
              key={index}
              className="grid grid-cols-[minmax(0,1fr)_auto_auto] items-center gap-2"
            >
              <Input
                value={row.value}
                onChange={(event) => updateValue(index, event.target.value)}
                onBlur={() => commit(rows)}
              />
              <RadioGroup
                value={
                  rows.findIndex((option) => filterBoolean(option.default)) === index
                    ? String(index)
                    : ""
                }
                onValueChange={() => setDefault(index)}
              >
                <RadioGroupItem value={String(index)} aria-label="Default distance" />
              </RadioGroup>
              <Button
                type="button"
                variant="ghost"
                size="icon-xs"
                aria-label="Remove distance"
                onClick={() => commit(rows.filter((_, rowIndex) => rowIndex !== index))}
              >
                <Trash2 />
              </Button>
            </div>
          ))}

          <div className="flex gap-2">
            <Input
              value={newValue}
              placeholder="Add distance"
              onChange={(event) => setNewValue(event.target.value)}
            />
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={!newValue.trim()}
              onClick={() => {
                commit([
                  ...rows,
                  {
                    value: newValue.trim(),
                    default: rows.length === 0,
                  },
                ])
                setNewValue("")
              }}
            >
              <Plus />
              Add
            </Button>
          </div>
        </div>
        <FieldDescription>The selected radio value is the default radius.</FieldDescription>
      </FieldContent>
    </Field>
  )
}
export function SearchFilterSettings(props: SchemaFieldSettingsProps) {
  return (
    <CommonSettings {...props}>
      <TextSetting
        label="Placeholder"
        value={props.field.placeholder}
        onChange={(placeholder) => props.onPatch({ placeholder })}
      />
      <SwitchSetting
        label="Search method fallback"
        checked={filterBoolean(props.field.searchFallback)}
        description="Use LIKE prefix search when FULLTEXT does not behave as expected."
        onChange={(searchFallback) => props.onPatch({ searchFallback })}
      />
      <TextSetting
        label="Width"
        value={props.field.width}
        onChange={(width) => props.onPatch({ width })}
      />
    </CommonSettings>
  )
}

export function DistanceFilterSettings(props: SchemaFieldSettingsProps) {
  const country = String(props.field.country ?? "")
  // Keep imported/custom and lowercase codes selectable without rewriting them.
  const countries = country && !FILTER_COUNTRIES.some((option) => option.value === country)
    ? [...FILTER_COUNTRIES, { value: country, label: FILTER_COUNTRIES.find((option) => option.value === country.toUpperCase())?.label ?? country }]
    : FILTER_COUNTRIES
  return (
    <CommonSettings {...props}>
      <TextSetting
        label="Placeholder"
        value={props.field.placeholder}
        onChange={(placeholder) =>
          props.onPatch({
            placeholder,
            addressFieldPlaceholder: placeholder,
          })
        }
      />

      <Field>
        <FieldContent>
          <FieldLabel>Distance control</FieldLabel>
          <FormBuilderChoice
            value={String(props.field.distanceControl || "select")}
            onValueChange={(distanceControl) =>
              props.onPatch({
                distanceControl,
                ...(distanceControl === "none"
                  ? distanceOptionsPatch(props.field, distanceOptions(props.field))
                  : {}),
              })
            }
            options={[
              { value: "select", label: "Select" },
              { value: "text", label: "Text input" },
              { value: "none", label: "Fixed default" },
            ]}
          />
        </FieldContent>
      </Field>

      <SwitchSetting
        label="User location button"
        checked={filterBoolean(props.field.userLocationButton)}
        onChange={(userLocationButton) => props.onPatch({ userLocationButton })}
      />

      <SwitchSetting
        label="Search by ZIP/postcode only"
        checked={filterBoolean(props.field.searchByZip)}
        onChange={(searchByZip) => props.onPatch({ searchByZip })}
      />

      {filterBoolean(props.field.searchByZip) ? (
        <TextSetting
          label="ZIP/postcode length"
          value={props.field.zipLength}
          onChange={(value) =>
            props.onPatch({
              zipLength: Number.parseInt(value, 10) || 5,
            })
          }
        />
      ) : null}
      <Field>
        <FieldContent>
          <FieldLabel>Country</FieldLabel>
          <FormBuilderChoice
            aria-label="Country"
            value={country}
            options={countries}
            emptyLabel="All countries"
            onValueChange={(country) => props.onPatch({ country })}
          />
          <FieldDescription>Limit address search results to the selected country.</FieldDescription>
        </FieldContent>
      </Field>

      <TextSetting
        label="Language"
        value={props.field.language}
        description="Optional geocoding language code."
        onChange={(language) => props.onPatch({ language })}
      />

      <Field>
        <FieldContent>
          <FieldLabel>Distance units</FieldLabel>
          <FormBuilderChoice
            value={String(props.field.distanceUnits || "km")}
            onValueChange={(distanceUnits) => props.onPatch({ distanceUnits })}
            options={[
              { value: "km", label: "Kilometers" },
              { value: "mi", label: "Miles" },
            ]}
          />
        </FieldContent>
      </Field>

      <TextSetting
        label="Distance units label"
        value={props.field.distanceUnitsLabel}
        onChange={(distanceUnitsLabel) => props.onPatch({ distanceUnitsLabel })}
      />

      <TextSetting
        label="From label"
        value={props.field.fromLabel}
        onChange={(fromLabel) => props.onPatch({ fromLabel })}
      />

      <DistanceOptionsSetting field={props.field} onPatch={props.onPatch} />
    </CommonSettings>
  )
}
