import { useCallback, useLayoutEffect, useMemo, useRef } from "react"
import type { SchemaFieldControlProps } from "./types"

/** Retire delayed adapter results before a replaced record can receive them. */
export function useControlRequest(props: SchemaFieldControlProps, adapter: unknown) {
  const owner = useMemo(
    () => ({}),
    [
      props.recordOwner,
      props.value,
      adapter,
      props.disabled,
      props.field.name,
      props.field.type,
      props.field.post_type,
      props.field.language,
      props.field.defaultMarkerPath,
    ],
  )
  const current = useRef<object | null>(null)
  const request = useRef(0)
  useLayoutEffect(() => {
    current.current = owner
    return () => {
      if (current.current === owner) current.current = null
      request.current++
    }
  }, [owner])
  const cancel = useCallback(() => {
    request.current++
  }, [])
  const begin = useCallback(() => {
    const run = ++request.current
    return () => current.current === owner && request.current === run
  }, [owner])
  const isCurrent = useCallback(() => current.current === owner, [owner])
  return { owner, begin, cancel, isCurrent }
}
