import { useEffect, useMemo, useState } from "react"
import { AlertCircle, ChevronDown, ChevronUp, GripVertical, Lock, Plus, Save } from "lucide-react"
import { Button } from "@/components/ui/button"
import { FormBuilderChoice } from "../FormBuilderChoice"
import type { ZodSettings } from "@/lib/mapsvg-api"
import { cn } from "@/lib/utils"
import { useDragSort } from "@/lib/use-drag-sort"
import type { FormFieldData } from "../../../../../mapsvg/FormBuilder/FieldDefinitions"
import {
  canAddSchemaField,
  cloneSchemaFields,
  createSchemaField,
  DEFAULT_SCHEMA_FIELD_TYPES,
  moveSchemaField,
  removeSchemaField,
  type SchemaBuilderFieldType,
  type SchemaBuilderValidationError,
  updateSchemaField,
  validateSchemaFields,
} from "./model"
import { complexSchemaFieldSettings } from "../complex-fields/settingsRegistry"
import { filterSchemaFieldSettings } from "../filter-fields/settingsRegistry"
import { locationSchemaFieldSettings } from "../location-field/settingsRegistry"
import { simpleSchemaFieldSettings } from "./settingsRegistry"
import type { SchemaFieldSettingsRegistry } from "./types"
import {
  cloneZodSettings,
  editableZodSettingsError,
  removeFieldValidation,
  renameFieldValidation,
  syncFieldValidation,
} from "./validation"

export type SchemaBuilderSaveState = {
  dirty: boolean
  valid: boolean
}

export type SchemaBuilderProps = {
  fields: FormFieldData[]
  hiddenFieldNames?: readonly string[]
  zodSettings?: ZodSettings | null
  onChange?: (fields: FormFieldData[]) => void
  onZodSettingsChange?: (settings: ZodSettings | null) => void
  onSave?: (fields: FormFieldData[], zodSettings: ZodSettings | null) => void | Promise<void>
  formId?: string
  showSaveButton?: boolean
  onSaveStateChange?: (state: SchemaBuilderSaveState) => void
  settingsRegistry?: Partial<SchemaFieldSettingsRegistry>
  settingsContext?: Record<string, unknown>
  fieldTypes?: readonly SchemaBuilderFieldType[]
  fieldTypeLabels?: Partial<Record<SchemaBuilderFieldType, string>>
  restrictedFieldTypes?: readonly SchemaBuilderFieldType[]
  onRestrictedFieldTypeSelect?: (type: SchemaBuilderFieldType) => void
  createField?: typeof createSchemaField
  validateFields?: (fields: FormFieldData[]) => SchemaBuilderValidationError[]
  saveButtonLabel?: string
  enableRecordValidation?: boolean
  className?: string
}

function typeLabel(type: string): string {
  if (type === "colorpicker") return "Color"
  if (type === "checkboxes") return "Checkboxes"
  return type.charAt(0).toUpperCase() + type.slice(1)
}

export function SchemaBuilder({
  fields,
  hiddenFieldNames = [],
  zodSettings = null,
  onChange,
  onZodSettingsChange,
  onSave,
  formId,
  showSaveButton = true,
  onSaveStateChange,
  settingsRegistry,
  settingsContext,
  fieldTypes = DEFAULT_SCHEMA_FIELD_TYPES,
  fieldTypeLabels = {},
  restrictedFieldTypes = [],
  onRestrictedFieldTypeSelect,
  createField = createSchemaField,
  validateFields = validateSchemaFields,
  saveButtonLabel = "Publish schema",
  enableRecordValidation = true,
  className,
}: SchemaBuilderProps) {
  const [draft, setDraft] = useState(() => cloneSchemaFields(fields))
  const [validationDraft, setValidationDraft] = useState<ZodSettings | null>(() =>
    cloneZodSettings(zodSettings),
  )
  const [selection, setSelectedIndex] = useState<number | null>(fields.length ? 0 : null)
  const [addType, setAddType] = useState<SchemaBuilderFieldType>(() => fieldTypes[0] ?? "text")
  useEffect(() => {
    const next = cloneSchemaFields(fields)
    setDraft(next)
    setSelectedIndex((current) => {
      if (!next.length) return null
      if (current == null) return 0
      return Math.min(current, next.length - 1)
    })
  }, [fields])

  useEffect(() => {
    setValidationDraft(cloneZodSettings(zodSettings))
  }, [zodSettings])

  const registry = useMemo(
    () => ({
      ...simpleSchemaFieldSettings,
      ...complexSchemaFieldSettings,
      ...locationSchemaFieldSettings,
      ...filterSchemaFieldSettings,
      ...(settingsRegistry ?? {}),
    }),
    [settingsRegistry],
  )
  const errors = useMemo(() => validateFields(draft), [draft, validateFields])
  const validationError = useMemo(
    () => editableZodSettingsError(validationDraft),
    [validationDraft],
  )
  // Keep hidden storage fields in the complete draft and payload, but give
  // selection, settings and move controls only the editable field indexes.
  const visibleIndexes = draft.flatMap((field, index) =>
    hiddenFieldNames.includes(String(field.name)) ? [] : [index],
  )
  const selectedIndex =
    selection != null && visibleIndexes.includes(selection)
      ? selection
      : (visibleIndexes[0] ?? null)
  const selectedField = selectedIndex == null ? undefined : draft[selectedIndex]
  const SelectedSettings = selectedField ? registry[selectedField.type] : undefined
  const dirty = useMemo(
    () =>
      JSON.stringify({ fields: draft, zodSettings: validationDraft }) !==
      JSON.stringify({ fields, zodSettings }),
    [draft, fields, validationDraft, zodSettings],
  )
  const valid = errors.length === 0 && !validationError

  useEffect(() => {
    onSaveStateChange?.({ dirty, valid })
  }, [dirty, onSaveStateChange, valid])

  const commitValidation = (next: ZodSettings | null) => {
    const cloned = cloneZodSettings(next)
    setValidationDraft(cloned)
    onZodSettingsChange?.(cloneZodSettings(cloned))
  }

  const commit = (
    next: FormFieldData[],
    nextSelected?: number | null,
    nextValidation: ZodSettings | null = validationDraft,
  ) => {
    setDraft(next)
    if (nextSelected !== undefined) {
      setSelectedIndex(nextSelected)
    }
    if (nextValidation !== validationDraft) {
      commitValidation(nextValidation)
    }
    onChange?.(cloneSchemaFields(next))
  }

  const addField = () => {
    if (restrictedFieldTypes.includes(addType)) { onRestrictedFieldTypeSelect?.(addType); return }
    if (!canAddSchemaField(addType, draft)) {
      return
    }
    const next = [...draft, createField(addType, draft)]
    commit(next, next.length - 1)
  }

  const removeField = (index: number) => {
    const next = removeSchemaField(draft, index)
    if (next === draft) {
      return
    }
    const removedName = String(draft[index]?.name ?? "")
    const nextValidation = removedName
      ? removeFieldValidation(validationDraft, removedName)
      : validationDraft
    const nextSelected = next.length ? Math.min(index, next.length - 1) : null
    commit(next, nextSelected, nextValidation)
  }

  const moveField = (from: number, to: number) => {
    const next = moveSchemaField(draft, from, to)
    if (next === draft) {
      return
    }

    let nextSelected = selectedIndex
    if (selectedIndex === from) {
      nextSelected = to
    } else if (selectedIndex != null && from < selectedIndex && selectedIndex <= to) {
      nextSelected = selectedIndex - 1
    } else if (selectedIndex != null && to <= selectedIndex && selectedIndex < from) {
      nextSelected = selectedIndex + 1
    }

    commit(next, nextSelected)
  }
  const dragSort = useDragSort(moveField)
  const patchField = (index: number, patch: Record<string, any>) => {
    const current = draft[index]
    if (!current) return

    const nextField = { ...current, ...patch }
    let nextValidation = validationDraft
    const oldName = String(current.name ?? "")
    const newName = String(nextField.name ?? "")
    if (oldName && newName && oldName !== newName) {
      nextValidation = renameFieldValidation(nextValidation, oldName, newName)
    }
    nextValidation = syncFieldValidation(nextValidation, nextField)
    commit(updateSchemaField(draft, index, patch), index, nextValidation)
  }

  const save = async () => {
    if (!onSave || !dirty || errors.length || validationError) {
      return
    }
    await onSave(cloneSchemaFields(draft), cloneZodSettings(validationDraft))
  }

  return (
    <div
      className={cn(
        "grid min-h-0 grid-cols-[minmax(260px,0.9fr)_minmax(320px,1.1fr)] overflow-hidden rounded-lg border",
        className,
      )}
    >
      {onSave && formId ? (
        <form
          id={formId}
          className="hidden"
          onSubmit={(event) => {
            event.preventDefault()
            void save()
          }}
        />
      ) : null}
      <div className="flex min-h-0 flex-col border-r">
        <div className="flex items-center gap-2 border-b p-3">
          <FormBuilderChoice
            aria-label="Field type"
            className="min-w-0 flex-1"
            value={addType}
            onValueChange={(value) => {
              const type = value as SchemaBuilderFieldType
              if (restrictedFieldTypes.includes(type)) onRestrictedFieldTypeSelect?.(type)
              else setAddType(type)
            }}
            options={fieldTypes.map((type) => ({
              value: type,
              label: `${fieldTypeLabels[type] ?? typeLabel(type)}${restrictedFieldTypes.includes(type) ? " · Premium" : ""}`,
              disabled: !restrictedFieldTypes.includes(type) && !canAddSchemaField(type, draft),
            }))}
          />
          <Button
            type="button"
            variant="outline"
            size="sm"
            disabled={!canAddSchemaField(addType, draft)}
            onClick={addField}
          >
            <Plus />
            Add
          </Button>
        </div>

        <div className="min-h-0 flex-1 overflow-auto p-2">
          <div className="grid gap-1">
            {draft.map((field, index) => {
              const position = visibleIndexes.indexOf(index)
              if (position < 0) return null
              const selected = selectedIndex === index
              const fieldErrors = errors.filter((error) => error.index === index)
              return (
                <div
                  key={`${field.type}-${field.name ?? ""}-${index}`}
                  {...dragSort.itemProps(index)}
                  className={cn(
                    "group flex items-center gap-1 rounded-md border p-1",
                    selected && "border-primary bg-accent",
                  )}
                >
                  <GripVertical className="size-4 shrink-0 cursor-grab text-muted-foreground" />
                  <button
                    type="button"
                    className="min-w-0 flex-1 rounded px-2 py-1.5 text-left"
                    onClick={() => setSelectedIndex(index)}
                  >
                    <div className="flex items-center gap-1.5">
                      <span className="truncate text-sm font-medium">
                        {field.label || field.name || typeLabel(field.type)}
                      </span>
                      {field.protected === true ? (
                        <Lock className="size-3 text-muted-foreground" />
                      ) : null}
                      {fieldErrors.length ? (
                        <AlertCircle className="size-3 text-destructive" />
                      ) : null}
                    </div>
                    <div className="truncate text-xs text-muted-foreground">
                      {field.name || "(no name)"} · {field.type}
                    </div>
                  </button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon-xs"
                    disabled={position === 0}
                    aria-label="Move field up"
                    onClick={() => moveField(index, visibleIndexes[position - 1]!)}
                  >
                    <ChevronUp />
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon-xs"
                    disabled={position === visibleIndexes.length - 1}
                    aria-label="Move field down"
                    onClick={() => moveField(index, visibleIndexes[position + 1]!)}
                  >
                    <ChevronDown />
                  </Button>
                </div>
              )
            })}
          </div>
        </div>

        {onSave && (showSaveButton || errors.length > 0 || Boolean(validationError)) ? (
          <div className="border-t p-3">
            {errors.length ? (
              <div className="mb-2 text-xs text-destructive">
                Fix {errors.length} schema error{errors.length === 1 ? "" : "s"} before saving.
              </div>
            ) : null}
            {validationError ? (
              <div className="mb-2 text-xs text-destructive">{validationError}</div>
            ) : null}
            {showSaveButton ? (
              <Button
                type="button"
                className="w-full"
                disabled={!dirty || Boolean(errors.length || validationError)}
                onClick={save}
              >
                <Save />
                {saveButtonLabel}
              </Button>
            ) : null}
          </div>
        ) : null}
      </div>
      <div className="min-h-0 overflow-auto p-5">
        {selectedField && selectedIndex != null ? (
          <>
            <div className="mb-5 border-b pb-4">
              <div className="text-base font-semibold">
                {selectedField.label || selectedField.name || typeLabel(selectedField.type)}
              </div>
              <div className="text-sm text-muted-foreground">
                {typeLabel(selectedField.type)} field
              </div>
            </div>

            {SelectedSettings ? (
              <SelectedSettings
                field={selectedField}
                fieldIndex={selectedIndex}
                errors={errors}
                context={settingsContext}
                validation={
                  !enableRecordValidation || validationError
                    ? undefined
                    : {
                        zodSettings: validationDraft,
                        onChange: commitValidation,
                      }
                }
                onPatch={(patch) => patchField(selectedIndex, patch)}
                onRemove={() => removeField(selectedIndex)}
              />
            ) : (
              <div className="rounded-md border border-dashed p-4 text-sm text-muted-foreground">
                Settings for “{selectedField.type}” are not available in the React schema editor
                yet. The field is preserved unchanged.
              </div>
            )}
          </>
        ) : (
          <div className="flex min-h-48 items-center justify-center text-sm text-muted-foreground">
            Add or select a field to edit its settings.
          </div>
        )}
      </div>
    </div>
  )
}
