import type { FormFieldData } from "../../../../../mapsvg/FormBuilder/FieldDefinitions"

export type SchemaFieldOption = {
  label?: string
  value?: string | number
  disabled?: boolean
  premium?: boolean
  title?: string
  options?: SchemaFieldOption[]
  [key: string]: any
}

export function fieldOptions(field: FormFieldData): SchemaFieldOption[] {
  const options = Array.isArray(field.options) ? (field.options as SchemaFieldOption[]) : []
  if (!field.optionsGrouped) {
    return options
  }

  return options.flatMap((group) => (Array.isArray(group.options) ? group.options : []))
}

export function optionValue(option: SchemaFieldOption): string {
  return option.value == null ? "" : String(option.value)
}

export function selectedOptionValues(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return []
  }

  return value.map((item) => {
    if (item && typeof item === "object" && "value" in item) {
      return String((item as { value: unknown }).value ?? "")
    }
    return String(item ?? "")
  })
}

export function buildLegacyMultiselectValue(
  field: FormFieldData,
  selectedValues: Iterable<string>,
): Array<{ label: string; value: string }> {
  const selected = new Set(selectedValues)
  return fieldOptions(field)
    .filter((option) => selected.has(optionValue(option)))
    .map((option) => ({
      label: option.label == null ? optionValue(option) : String(option.label),
      value: optionValue(option),
    }))
}

export function nextSchemaFormRecord(
  record: Record<string, any>,
  name: string,
  value: unknown,
): Record<string, any> {
  return { ...record, [name]: value }
}

export function buildLegacyCheckboxValues(
  field: FormFieldData,
  selectedValues: Iterable<string>,
): string[] {
  const selected = new Set(selectedValues)
  return fieldOptions(field)
    .map(optionValue)
    .filter((value) => selected.has(value))
}

export function schemaFields(schema: import("./types").SchemaFormSchema): FormFieldData[] {
  if (Array.isArray(schema)) {
    return schema
  }
  return Array.isArray(schema.fields) ? schema.fields : []
}
