export type RecordValidationIssue = {
  path: Array<string | number>
  message: string
  keyword?: string
}

export type RecordValidationErrorDetails = {
  code: string
  issues: RecordValidationIssue[]
}

const RECORD_VALIDATION_CODES = new Set([
  "record_validation_failed",
  "record_validation_schema_invalid",
  "record_validation_configuration_error",
  "operation_validation_failed",
])

function validationIssue(value: unknown): RecordValidationIssue | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null
  const issue = value as Record<string, unknown>
  if (!Array.isArray(issue.path) || typeof issue.message !== "string") return null
  if (!issue.path.every((part) => typeof part === "string" || typeof part === "number")) {
    return null
  }
  return {
    path: issue.path as Array<string | number>,
    message: issue.message,
    keyword: typeof issue.keyword === "string" ? issue.keyword : undefined,
  }
}

export function recordValidationErrorDetails(error: unknown): RecordValidationErrorDetails | null {
  if (!error || typeof error !== "object") return null

  const candidate = error as Record<string, unknown>
  const code = candidate.code
  const rawIssues = candidate.issues
  if (typeof code !== "string" || !RECORD_VALIDATION_CODES.has(code) || !Array.isArray(rawIssues)) {
    return null
  }

  const issues = rawIssues
    .map(validationIssue)
    .filter((issue): issue is RecordValidationIssue => !!issue)
  if (issues.length === 0) return null

  return { code, issues }
}

export function isRecordValidationError(error: unknown): boolean {
  return recordValidationErrorDetails(error) !== null
}

function pathSuffix(path: Array<string | number>): string {
  return path.slice(1).reduce<string>((result, part) => {
    if (typeof part === "number") return `${result}[${part}]`
    return result ? `${result}.${part}` : part
  }, "")
}

export function groupRecordValidationIssues(issues: RecordValidationIssue[]): {
  fields: Map<string, string[]>
  root: string[]
} {
  const fields = new Map<string, string[]>()
  const root: string[] = []

  const pushUnique = (target: string[], message: string) => {
    if (!target.includes(message)) target.push(message)
  }

  for (const issue of issues) {
    const field = issue.path[0]
    if (typeof field !== "string" || field === "") {
      pushUnique(root, issue.message)
      continue
    }

    const suffix = pathSuffix(issue.path)
    const message = suffix ? `${suffix}: ${issue.message}` : issue.message
    const current = fields.get(field) ?? []
    pushUnique(current, message)
    fields.set(field, current)
  }

  return { fields, root }
}
