import {
  FormBuilderCombobox,
  type FormBuilderComboboxOption,
} from "@/components/form-builder/FormBuilderCombobox"
import { FormBuilderSelect } from "@/components/form-builder/FormBuilderSelect"

type Props = {
  value: string
  onValueChange: (value: string) => void
  options: FormBuilderComboboxOption[]
  emptyLabel?: string
  placeholder?: string
  disabled?: boolean
  className?: string
  id?: string
  "aria-label"?: string
  title?: string
  "data-testid"?: string
}

/** Choices share the existing form widgets and search threshold. */
export function FormBuilderChoice(props: Props) {
  const Component =
    props.options.length + (props.emptyLabel ? 1 : 0) > 3 ? FormBuilderCombobox : FormBuilderSelect
  return <Component {...props} />
}
