import type { ZodSettings } from "@/lib/mapsvg-api"
import type { FormFieldData } from "../../../../../mapsvg/FormBuilder/FieldDefinitions"
import { fieldOptions, optionValue } from "../schema-form/value"

export type JsonSchemaObject = Record<string, unknown>
export type FieldValidationType = "string" | "number" | "integer" | "boolean" | "array" | "object"
export type EditableFieldValidationType = FieldValidationType | "custom" | null

const JSON_SCHEMA_DRAFT = "https://json-schema.org/draft/2020-12/schema"

const KNOWN_STRING_KEYS = ["minLength", "maxLength", "pattern", "format"] as const
const KNOWN_NUMBER_KEYS = [
  "minimum",
  "maximum",
  "exclusiveMinimum",
  "exclusiveMaximum",
  "multipleOf",
] as const
const KNOWN_ARRAY_KEYS = ["minItems", "maxItems", "items"] as const
const KNOWN_OBJECT_KEYS = ["minProperties", "maxProperties", "properties", "required"] as const

function isRecord(value: unknown): value is JsonSchemaObject {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value)
}

function cloneJson<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T
}

export function cloneZodSettings(settings?: ZodSettings | null): ZodSettings | null {
  return settings ? cloneJson(settings) : null
}

export function parseValidationRoot(settings?: ZodSettings | null): JsonSchemaObject | null {
  if (!settings) return null
  if (settings.version !== 1 || typeof settings.jsonSchema !== "string") {
    throw new Error("Invalid zodSettings envelope.")
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(settings.jsonSchema)
  } catch {
    throw new Error("Invalid zodSettings JSON Schema.")
  }

  if (!isRecord(parsed)) {
    throw new Error("Record validation schema must be a JSON object.")
  }
  return parsed
}

function createRoot(): JsonSchemaObject {
  return {
    $schema: JSON_SCHEMA_DRAFT,
    type: "object",
    properties: {},
  }
}

function editableRoot(settings?: ZodSettings | null): JsonSchemaObject {
  const root = cloneJson(parseValidationRoot(settings) ?? createRoot())
  if (root.type !== undefined && root.type !== "object") {
    throw new Error("Record validation root must have type object.")
  }
  if (root.type === undefined) {
    root.type = "object"
  }
  if (root.properties !== undefined && !isRecord(root.properties)) {
    throw new Error("Record validation properties must be an object.")
  }
  if (root.required !== undefined) {
    if (!Array.isArray(root.required) || root.required.some((name) => typeof name !== "string")) {
      throw new Error("Record validation required must be an array of field names.")
    }
  }
  return root
}

export function editableZodSettingsError(settings?: ZodSettings | null): string | null {
  if (!settings) return null
  try {
    editableRoot(settings)
    return null
  } catch (error) {
    return error instanceof Error ? error.message : String(error)
  }
}

function settingsFromRoot(root: JsonSchemaObject, previous?: ZodSettings | null): ZodSettings {
  return {
    ...(previous ? cloneJson(previous) : {}),
    version: 1,
    jsonSchema: JSON.stringify(root),
  }
}

function properties(root: JsonSchemaObject): JsonSchemaObject {
  if (root.properties === undefined) {
    const next: JsonSchemaObject = {}
    root.properties = next
    return next
  }
  if (!isRecord(root.properties)) {
    throw new Error("Record validation properties must be an object.")
  }
  return root.properties
}

function requiredFields(root: JsonSchemaObject): string[] {
  if (root.required === undefined) return []
  if (!Array.isArray(root.required) || root.required.some((name) => typeof name !== "string")) {
    throw new Error("Record validation required must be an array of field names.")
  }
  return root.required as string[]
}

export function getFieldValidationNode(
  settings: ZodSettings | null | undefined,
  name: string,
): JsonSchemaObject | null {
  const root = parseValidationRoot(settings)
  if (!root || !isRecord(root.properties)) return null
  const node = root.properties[name]
  return isRecord(node) ? node : null
}

export function getFieldValidationType(node: JsonSchemaObject | null): EditableFieldValidationType {
  if (!node) return null
  const type = node.type
  if (typeof type === "string") {
    return isFieldValidationType(type) ? type : "custom"
  }
  if (Array.isArray(type)) {
    const withoutNull = type.filter((value) => value !== "null")
    if (
      withoutNull.length === 1 &&
      typeof withoutNull[0] === "string" &&
      isFieldValidationType(withoutNull[0])
    ) {
      return withoutNull[0]
    }
  }
  return "custom"
}

export function isFieldNullable(node: JsonSchemaObject | null): boolean {
  return Boolean(node && Array.isArray(node.type) && node.type.includes("null"))
}

export function isFieldRequired(settings: ZodSettings | null | undefined, name: string): boolean {
  const root = parseValidationRoot(settings)
  return root ? requiredFields(root).includes(name) : false
}

function isFieldValidationType(value: string): value is FieldValidationType {
  return ["string", "number", "integer", "boolean", "array", "object"].includes(value)
}

export function suggestedValidationType(field: FormFieldData): FieldValidationType {
  if (field.type === "number") return "number"
  if (field.type === "checkbox" || field.type === "boolean") return "boolean"
  if (field.type === "checkboxes") return "array"
  if (field.type === "select" && field.multiselect === true) return "array"
  if (["image", "region", "relation"].includes(field.type)) return "array"
  if (["post", "location"].includes(field.type)) return "object"
  return "string"
}

function cleanupTypeSpecificKeywords(node: JsonSchemaObject, type: FieldValidationType): void {
  const keep = new Set<string>()
  if (type === "string") KNOWN_STRING_KEYS.forEach((key) => keep.add(key))
  if (type === "number" || type === "integer") {
    KNOWN_NUMBER_KEYS.forEach((key) => keep.add(key))
  }
  if (type === "array") KNOWN_ARRAY_KEYS.forEach((key) => keep.add(key))
  if (type === "object") KNOWN_OBJECT_KEYS.forEach((key) => keep.add(key))

  for (const key of [
    ...KNOWN_STRING_KEYS,
    ...KNOWN_NUMBER_KEYS,
    ...KNOWN_ARRAY_KEYS,
    ...KNOWN_OBJECT_KEYS,
    "enum",
  ]) {
    if (!keep.has(key)) delete node[key]
  }
}

function choiceValues(field: FormFieldData): string[] {
  return fieldOptions(field)
    .map(optionValue)
    .filter((value) => value !== "")
}

function syncChoiceKeywords(node: JsonSchemaObject, field: FormFieldData): void {
  const type = getFieldValidationType(node)
  const values = choiceValues(field)

  if (
    type === "string" &&
    (field.type === "radio" ||
      field.type === "status" ||
      (field.type === "select" && field.multiselect !== true))
  ) {
    node.enum = values
    return
  }

  if (type === "array" && field.type === "checkboxes") {
    const currentItems = isRecord(node.items) ? cloneJson(node.items) : {}
    currentItems.type = "string"
    currentItems.enum = values
    node.items = currentItems
    return
  }

  delete node.enum
  if (field.type === "checkboxes" && isRecord(node.items)) {
    const items = cloneJson(node.items)
    delete items.enum
    if (Object.keys(items).length === 0) delete node.items
    else node.items = items
  }
}

export function setFieldValidationType(
  settings: ZodSettings | null | undefined,
  field: FormFieldData,
  type: FieldValidationType | null,
): ZodSettings | null {
  const name = String(field.name ?? "")
  if (!name) return settings ?? null
  if (!settings && type === null) return null

  const root = editableRoot(settings)
  const props = properties(root)

  if (type === null) {
    delete props[name]
    const required = requiredFields(root).filter((fieldName) => fieldName !== name)
    if (required.length) root.required = required
    else delete root.required
    return settingsFromRoot(root, settings)
  }

  const node = isRecord(props[name]) ? cloneJson(props[name]) : {}
  const nullable = isFieldNullable(node)
  cleanupTypeSpecificKeywords(node, type)
  node.type = nullable ? [type, "null"] : type
  syncChoiceKeywords(node, field)
  props[name] = node
  return settingsFromRoot(root, settings)
}

export function setFieldRequired(
  settings: ZodSettings | null | undefined,
  name: string,
  required: boolean,
): ZodSettings | null {
  if (!settings) return null
  const root = editableRoot(settings)
  const current = requiredFields(root).filter((fieldName) => fieldName !== name)
  if (required) current.push(name)
  if (current.length) root.required = current
  else delete root.required
  return settingsFromRoot(root, settings)
}

export function setFieldNullable(
  settings: ZodSettings | null | undefined,
  name: string,
  nullable: boolean,
): ZodSettings | null {
  if (!settings) return null
  const root = editableRoot(settings)
  const props = properties(root)
  const node = isRecord(props[name]) ? cloneJson(props[name]) : null
  if (!node) return settings
  const type = getFieldValidationType(node)
  if (!type || type === "custom") return settings

  node.type = nullable ? [type, "null"] : type
  props[name] = node
  return settingsFromRoot(root, settings)
}

export function setFieldValidationKeyword(
  settings: ZodSettings | null | undefined,
  name: string,
  keyword: string,
  value: unknown,
): ZodSettings | null {
  if (!settings) return null
  const root = editableRoot(settings)
  const props = properties(root)
  const node = isRecord(props[name]) ? cloneJson(props[name]) : null
  if (!node) return settings

  if (value === undefined || value === null || value === "") delete node[keyword]
  else node[keyword] = value
  props[name] = node
  return settingsFromRoot(root, settings)
}

export function syncFieldValidation(
  settings: ZodSettings | null | undefined,
  field: FormFieldData,
): ZodSettings | null {
  if (!settings) return null
  const name = String(field.name ?? "")
  if (!name) return settings
  const root = editableRoot(settings)
  const props = properties(root)
  const node = isRecord(props[name]) ? cloneJson(props[name]) : null
  if (!node) return settings

  syncChoiceKeywords(node, field)
  props[name] = node
  return settingsFromRoot(root, settings)
}

export function renameFieldValidation(
  settings: ZodSettings | null | undefined,
  oldName: string,
  newName: string,
): ZodSettings | null {
  if (!settings || !oldName || oldName === newName) return settings ?? null

  const root = editableRoot(settings)
  const props = properties(root)
  if (Object.prototype.hasOwnProperty.call(props, oldName)) {
    props[newName] = props[oldName]
    delete props[oldName]
  }

  const nextRequired = requiredFields(root).map((name) => (name === oldName ? newName : name))
  const uniqueRequired = [...new Set(nextRequired)]
  if (uniqueRequired.length) root.required = uniqueRequired
  else delete root.required

  return settingsFromRoot(root, settings)
}

export function removeFieldValidation(
  settings: ZodSettings | null | undefined,
  name: string,
): ZodSettings | null {
  return setFieldValidationType(settings, { type: "text", name }, null)
}
